import { _decorator, Component, Label, log, Material, Node, sp, Sprite } from 'cc';
import { GameDataDefine } from '../../GameDataDefine';
const { ccclass, property, menu } = _decorator;

@ccclass('JackpotItem')
export class JackpotItem extends Component {
    /**条件满足后特效 */
    @property({ type: Node })
    private winnerEffect: Node = null;
    /**第一段动画播放时遮罩 */
    @property({ type: Node })
    private winnerMark: Node = null;
    /**条件满足后奖励值 */
    @property({ type: Label })
    private rapidVal: Label = null;
    /**金币数字动画节点播放 */
    @property({ type: Node })
    private numNode: Node = null;
    /**数字 */
    @property({ type: Node })
    private numImageNode: Node = null;
    /**中奖后图片 */
    @property({ type: Node })
    private winImageNode: Node = null;

    /**存储当前条件满足后特效的ske */
    private ske ;
    /**存储当前条件满足后特效的ske */
    private numSke;
    private _itemInfo: any = null;
    protected onLoad(): void {
        this.winnerMark.active = false;
    }

    public setItemInfo(itemInfo: any){
        this._itemInfo = itemInfo;
        this.numImageNode.active = true;
        this.numNode.active = false;
        this.winImageNode.active = false;
        this.setItemVal(true, itemInfo.reward);
        this.refreshJackpotItem();
    }
    
    public getItemInfo(): any {
        return this._itemInfo;
    }

    private TIME = 200;
    public setItemCountEffect(){  
        let id = this._itemInfo.id || 1
        let timer = this.TIME * (id - 1);
        setTimeout(()=> {
            
            // 展示金币值少1动画 
            if(this.numNode){
                this.numNode.active = true;
                this.numImageNode.active = false;
                this.winImageNode.active = false;
            }
            
            if (this.numSke && this.numSke.state && this.numSke.state.getCurrent(0)) {
                this.numSke.state.getCurrent(0).stop();
                this.numSke?.clearTracks(); // 会导致同时飞两个Rapid时，但只点亮最大的那一个。
            }
            
            let animNum = this._itemInfo.id + 5 - GameDataDefine.rapidhitCount;
            if (animNum <= 0) {
                this.numNode.active = false;
            }
            this.numSke = this.numNode.getComponent(sp.Skeleton);
            this.numSke.setAnimation(0, `${animNum}`, false);
            this.numSke.setCompleteListener((x: sp.spine.TrackEntry)=>{
            });
        }, timer)   
    }

    public refreshJackpotItem(){

        if(GameDataDefine.rapidhitCount >= this._itemInfo.count){
            this.setItemEffect(true);
        }else{
            this.setItemEffect(false);
        }
        console.log("==========refreshJackpotItem============", GameDataDefine.rapidhitCount);
    }
    
    public setItemEffect(isShow:boolean){
        if(this.winnerEffect){
            this.winnerEffect.active = isShow;
        }
        if(!isShow){
            return;
        }
        this.winnerMark.active = true;
        let idx = this.node.children.length;
        this.winnerEffect.setSiblingIndex(idx);

        if (this.ske && this.ske.state && this.ske.state.getCurrent(0)) {
            this.ske.state.getCurrent(0).stop();
            this.ske?.clearTracks(); // 会导致同时飞两个Rapid时，但只点亮最大的那一个。
        }

        this.ske = this.winnerEffect.getComponent(sp.Skeleton);
        this.ske.setAnimation(0, `line${this._itemInfo.id}`, false);
        this.ske.setCompleteListener((x: sp.spine.TrackEntry)=>{
            let name = x.animation?.name ?? "";
            for (let index = 0; index < GameDataDefine.curSkeRapid.length; index++) {
                if (index < this._itemInfo.id && GameDataDefine.curSkeRapid[index]) {
                    GameDataDefine.curSkeRapid[index].active = false;
                    GameDataDefine.curSkeRapid[index] = null;
                }           
            }

            if(name == `line${this._itemInfo.id}`){
                this.winnerEffect.setSiblingIndex(1);
                this.winnerMark.active = false;
            }
            GameDataDefine.curSkeRapid[this._itemInfo.id] = this.winnerEffect;
        });
        this.ske.addAnimation(0, `line${this._itemInfo.id}_fire`,true);
    }
    
    //设置阶段奖励值
    private setItemVal(isShow:boolean, val:number = 0){
        if(this.rapidVal){
            this.rapidVal.node.active = isShow;
            if (Number.isInteger(val)) {
                this.rapidVal.string = `${val}.00`;
            }
            else if (this.isOneDecimalNumber(val)) {
                this.rapidVal.string = `${val}0`;
            }
            else {
                this.rapidVal.string = `${val}`;
            }
        }
    }

    // 判断是否是1位数小数
    private isOneDecimalNumber(num: number): boolean {
        const str = num.toString();
        const regex = /^\d+\.\d$/;
        return regex.test(str) && parseFloat(str.split('.')[1]).toString().length === 1;
    }
}


