import { game, macro } from "cc";
import { EntryManager } from "../../../scripts/framework/hall/entry/EntryManager";
import { ENTRY_CONFIG } from "../../../scripts/framework/hall/HallDefind";
import { UIManager } from "../../../scripts/framework/ui/UIManager";
import { HotUpdate } from "../../../scripts/framework/update/IHotUpdate";
import { GameBaseEntry } from "../../gamesCommon/script/GameBaseEntry";
import { Config, RES } from "./Config";
import { UICF, UIID_GAME } from "./UIDefined";
import { GameCommonManager } from "../../gamesCommon/script/GameCommonManager";
import { ServerProxy } from "./net/ServerProxy";

class GameEntry extends GameBaseEntry {

    static bundle: string = RES.bundleName;

    protected onLoadBundleComplete(cb: Function): void {
        // macro.ENABLE_MULTI_TOUCH = false
        game.frameRate = 60;
        RES.init();
        RES.loadSources(async () => {
            Log.d(Config.logTag, `openGameView game 3513`);
            UIManager.getInstance().setUIConf(UICF);
            await UIManager.getInstance().open(UIID_GAME.MainView);
            ServerProxy.getInstance().registerMsgMap()
            GameCommonManager.getInstance().showPlaybackView();
            if (cb) cb();
        }, this);
    }

    // protected closeGameView(): void {

    // }
}
EntryManager.getInstance().register(GameEntry);