import { _decorator, Component, Node, Sprite, SpriteFrame } from "cc";
import { ResManager } from "../../../../../scripts/framework/manager/ResManager";
import { Global } from "../../../../../scripts/main/Global";
import { RES } from "../../Config";
import { Timer } from "../../utils/Timer";
import { MainComBase } from "./MainComBase";
const { ccclass, property } = _decorator;

export class LineCom extends MainComBase {
  private _group_line: Node;
  private _lineItem: LineItem[];
  private _timeDelay: number = 500;
  private _timesKey: number = 0;
  private _showlineArr: number[] = [];
  protected _init() {
    this._lineItem = [];
    this._showlineArr = [];
    this._group_line = this._comRoot.getChildByName("group_lines");
    for (let i = 0; i < 9; i++) {
      let root = this._group_line.getChildByName(`line_${i}`);
      let line = new LineItem(root, i);
      line.showWinLineByState();
      this._lineItem.push(line);
    }
    this.hideAllLine();
  }

  public hideAllLine() {
    Timer.clearTimeOut(this._timesKey);
    this._lineItem.forEach((line) => {
      line.hide();
    });
    // Log.e("隐藏所有中奖线");
  }

  public showLines(lineNums: number[], hideOther: boolean = true) {
    this._showlineArr = lineNums;
    // if (hideOther == true) {
    //     this.hideAllLine();
    // }
    this.showWinline();
    this._timesKey = Timer.setTimeOut(
      this,
      this.showWinline,
      this._timeDelay,
      null,
      0
    );
  }

  private showWinline(): void {
    this.hideAllLine();
    let index: number;
    for (let value of this._showlineArr) {
      index = value - 1;
      let line = this._lineItem[index];
      if (line) {
        line.showWinLineByState();
      }
    }
  }

  protected _addEvent(): void {}

  protected _removeEvent(): void {}
}

export class LineItem {
  private _root: Node;
  /**线图标 */
  private _img_frame: Node;
  private _lineId: number;
  constructor(root: Node, lineId: number) {
    this._root = root;
    this._lineId = lineId + 1;
    this._img_frame = this._root.getChildByName("img_line");
    this.showWinLineByState();
  }

  public showWinLineByState() {
    this._img_frame.active = !this._img_frame.active;
  }
  public hide(): void {
    this._img_frame.active = false;
  }
}
