import { _decorator, Component, instantiate, Node, Prefab, sp, tween, Tween, UIOpacity, UITransform, Vec3 } from 'cc';
import { Item } from './Item';
import { Config } from '../../Config';
import { IconData } from '../../GameDataDefine';
import { GameComUtils } from '../../../../gamesCommon/script/utils/GameComUtils';
const { ccclass, property } = _decorator;

/** 普通Spin停止时的回弹时间 */
const htDuration: number = 0.075;
/** 快速Spin: 停止时的回弹时间(向下停止和向上回弹都使用该时间) */
const qsStopElastyD: number = 0.144/2;
// 普通
const elastyUp: number = 45; // 173*0.26;
const elastyDown: number = 30;
// 快速
const elastyQiuckDown: number = 18; // 20*437/486;

@ccclass("CrazyWildModel")
export class CrazyWildModel extends Component {

    @property({ type: [Node] })
    private listView: Node[] = [];

    @property({ type: Node, tooltip: "anim/carzy_wild/carzy_wild" })
    private smokeEffect: Node = null!;

    @property({ type: Node, tooltip: "anim/carzy_wild/carzy_wild2" })
    private smokeEffect2: Node = null!;

    private _listTag:number = 0;
    private showTime:number = 10;

    onLoad(){
        
    }

    update(dt: number){
        if(this.showTime > 0){
            this.showTime -= dt;
        }else{
            this.stopAnim();
        }
    }
    
    public reset(_shoTime:number){
        this.node.active = true;
        this.showTime = _shoTime;
    }

    public play(listTag:number){
        this._listTag = listTag;
        let showList = this.listView[this._listTag];
        this._addFireEffect(showList);

        let _contentHeight = showList.getComponent(UITransform)?.height!;
        let nodeEmo = this.node.getChildByName("small_emo");
        console.log("====CrazyWildModel==1=====play ==", nodeEmo);

        if (nodeEmo) {       
            for (let i = 0; i < 4; i++) {
                let wildItem = instantiate(nodeEmo);
                let itemHeight = wildItem.getComponent(UITransform)?.height!;
                wildItem.setPosition(0, _contentHeight, 0);
                showList.addChild(wildItem);
                wildItem.active = false;
                // GameComUtils.fadeIn(wildItem, null, 5);
                // GameComUtils.fadeOut(wildItem, null, 5);
                
                tween(showList).delay(0.1*i).call(()=>{
                    this._playAnim(wildItem, _contentHeight, itemHeight);
                }).start();
            }
        }
    }

    private _playAnim(wildItem:Node, _contentHeight:number, itemHeight:number){
        let opa = wildItem.getComponent(UIOpacity);
        opa.opacity = 10;
        
        GameComUtils.fadeIn(wildItem, null, 5);
        let onFirstStep = () => { // 开始位置+SubGameConstants.spinningAnimStartUpOffsetY
            wildItem.active = true;
        };
        let onFinish = () => { // 回正
            wildItem.active = false;
        };
        
        let TIME = 0.3;
        let TIME1 = 0.4;
        let TIME2 = 0.3;
        let TIME3 = 0.5;
        let act0 = tween(wildItem)
            .to(0, {position: new Vec3(0, _contentHeight)})
            .to(0, {scale: new Vec3(2, 2)})
            // .delay(TIME)
            .call(onFirstStep);
        let act1 = tween(wildItem)
            .to(TIME1, {scale: new Vec3(1, 1)}, {easing: "sineOut"});//, {easing: "backIn"}
        let posY = _contentHeight - itemHeight / 2;
        let act2 = tween(wildItem)
            .to(TIME2, {position: new Vec3(0, posY)}, {easing: "sineOut"})
            .to(TIME3, {position: new Vec3(0, posY - 3*itemHeight)}, {easing: "sineIn"});
        
            
        // tween(opa)
        // .to(0.8, {opacity:0})
        // .to(2, {opacity:255})
        // .delay(0.3)
        // .repeatForever()
        // .start();
        
        let act3 = tween(wildItem).parallel(act1, act2);
        let act4 = tween(wildItem).delay(0.1).call(onFinish);
        tween(wildItem).sequence(act0, act3, act4).repeatForever().start(); 
    }


    private _addFireEffect(parentNode:any){
        let effSmoke = instantiate(this.smokeEffect);
        effSmoke.parent = parentNode;
        effSmoke.active = true;
        let h = parentNode.getComponent(UITransform)?.height;
        if(h){
            effSmoke.setPosition(0, h / 2 - 30);
        }
        let ske = effSmoke?.getComponent(sp.Skeleton)
        if (ske) {
            ske?.setAnimation(0, 'animation', false);
    
            tween(this.smokeEffect2)
            .delay(1)
            .call(()=>{
                this.smokeEffect2.active = true;
            })
            .start();
        }
    }

    public setShowTime() {
        this.showTime = 0;
    }

    //===============================================
    //=================== 内部接口 ===================
    //===============================================

    public stopAnim(){
        if (this.listView) {
            for (let i = 0; i < this.listView.length; i++) {
                let showList = this.listView[i];
                Tween.stopAllByTarget(showList);
                showList.removeAllChildren();
            }
        }
        
        if (this.smokeEffect2) {
            this.smokeEffect2.active = false;
            this.node.active = false;
        }
    }
    
}


