import { _decorator, Component, Node, Label } from 'cc';
import { Utils } from '../utils/Utils';
import { GameEventType } from '../../../gamesCommon/script/GameEventType';
import { RollMenu } from '../../../rollCommon/script/views/RollMenu';
import { RollBottom } from './RollBottom-320000001';
import { RollCommonModel } from '../../../rollCommon/script/RollCommonModel';
import { Eventer } from '../../../../scripts/framework/Eventer';
import { SpinRollMenu } from '../view/main/SpinRollMenu';

const { ccclass, property } = _decorator;

/** 此类只供参考，具体由具体游戏实现自己写一份 */
@ccclass('RollFunView_320000001')
export class RollFunView extends Component {
    @property(SpinRollMenu)
    public menu: SpinRollMenu;
    @property(RollBottom)
    public bottom: RollBottom;
    @property(Label)
    public tips0: Label;
    @property(Label)
    public tips1: Label;
    @property(Node)
    public tips2Node: Node;
    @property(Label)
    public tips2: Label;
    public isFreeShow;

    @property(Node)
    public autoPlay: Node;

    @property({
        type: Number,
        displayName: "横竖屏",
        tooltip: "1为横屏 2为竖屏",
    })
    public screenType: Number;

    protected onLoad(): void {
        this.addToStage();
        // this.bottom.init();
        // this.autoPlay.node.active = false;
    }

    start() {
        if (this.tips0) {
            this.tips0.node.active = false;
        }
        if (this.tips1) {
            this.tips1.node.active = false;
        }
        if (this.tips2Node) {
            this.tips2Node.active = false;
        }
    }

    protected onDestroy(): void {
        this.removeFromStage();
    }

    public showTips0(isShow: boolean, text?: string) {
        if (this.tips0) {
            this.tips0.node.active = isShow;
            if (isShow) {
                this.tips0.string = text;
            }
        }
    }

    public showTips1(isShow: boolean, text?: string) {
        if (this.tips1) {
            this.tips1.node.active = isShow;
            if (isShow) {
                this.tips1.string = text;
            }
        }
    }

    public showTips2(isShow: boolean, text?: string) {
        if (this.tips2Node) {
            this.tips2Node.active = isShow;
            if (isShow && this.tips2) {
                this.tips2.string = text;
            }
        }
    }

    private freeShow(data) {
        this.isFreeShow = data.data.isFreeShow
        this.bottom.setSpecialBtnShow(this.isFreeShow)
    }

    private onMenuClick() {
        console.log("SpinBottomView onMenuClick");
        this.menu.onMenu();

        // let type = this.screenType == 1 ? ScreenType.Landscape : ScreenType.Portrait;
        // if (Global.gameScreenType == type)
        //     this.menu.onMenu();
    }

    private onAutoClick(times) {
        RollCommonModel.getInstance().autoPlayTime = times;
    }

    private onAutoClose() {
        // if (this.autoPlay.node.active)
        //     this.bottom.setAutoCloseNotDisplay();
        // this.autoPlay.node.active = false;
        // RollCommonModel.getInstance().isOpenAutoMenu = false;
    }

    private onBgClose() {
        this.onAutoClose();
    }

    /** 自动spin界面是否打开 */
    isOpenAuto() {
        // return this.autoPlay.node.active;
    }


    protected addToStage() {
        Eventer.getInstance().on(GameEventType.RollMenuClick, this.onMenuClick, this);
        Eventer.getInstance().on(GameEventType.RollAutoPlayClick, this.onAutoClick, this);
        Eventer.getInstance().on(GameEventType.RollCloseAutoPlayMenu, this.onAutoClose, this);
        Eventer.getInstance().on(GameEventType.RollBackgroundClick, this.onBgClose, this);
    }

    protected removeFromStage() {
        Eventer.getInstance().offName(GameEventType.RollMenuClick, this);
        Eventer.getInstance().offName(GameEventType.RollAutoPlayClick, this);
        Eventer.getInstance().offName(GameEventType.RollCloseAutoPlayMenu, this);
        Eventer.getInstance().offName(GameEventType.RollBackgroundClick, this);
    }
}



