import { Node } from "cc";
import { MainView } from "./MainView";

export abstract class MainComBase {
    /**组件根节点 */
    protected _comRoot: Node;
    /**游戏主界面 */
    protected _mainView: MainView;

    public constructor(comRoot: Node, mainView: MainView) {
        this._comRoot = comRoot;
        this._mainView = mainView;
    }

    public init() {
        this._init();
        this._addEvent();
    }

    /**初始化组件 */
    protected abstract _init(): void;

    /**添加事件 */
    protected abstract _addEvent(): void;

    /**移除事件 */
    protected abstract _removeEvent(): void;

    /**销毁 */
    public destroy() {
        this._removeEvent();
    }

    /**
     * 每一帧刷新 
     * @param deltaTime 单位ms
     */
    public update(deltaTime: number) {

    }
}
