import { _decorator, Component, Label, Node, NodeEventType } from 'cc';
import { Eventer } from '../../../../scripts/framework/Eventer';
import { Config } from '../Config';
import { GameEventType } from '../../../gamesCommon/script/GameEventType';
import { UIButton } from '../../../../scripts/framework/ui/basic_ui/UIButton';
const { ccclass, property } = _decorator;

@ccclass('BuyGameCom')
export class BuyGameCom extends Component {
    @property(Label)
    private score: Label;
    @property(UIButton)
    private cancal_btn: UIButton;
    @property(UIButton)
    private check_btn: UIButton;
    @property(Node)
    private mask: Node;
    start() {
        this.initBtns();
    }

    public initBtns(): void {
        //this.node.active = false;
        this.onEven();
    }

    protected onEven() {
        this.cancal_btn.touchEndedFun = this.hide.bind(this);
        this.check_btn.touchEndedFun = this.onBuyGame.bind(this);
        this.mask.on(NodeEventType.TOUCH_END, this.hide, this);
    }

    private offEvent(): void {
        // this.mask.off(NodeEventType.TOUCH_END, this.hide, this);
    }

    protected onDestroy(): void {
        this.offEvent();
    }
    protected onBuyGame(): void {
        this.hide();
        Config.inBuyGame = true;
        Eventer.getInstance().emit(GameEventType.RollStart);
    }

    public hide(): void {
        this.node.active = false;
        Config.inBuyGame = false;
    }
    public hideNode(): void {
        this.node.active = false;
    }
    public set scoreStr(str: string) {
        this.score.string = str;
    }
}

