    /**
     * 计算中奖信息
     * @param iconArr 盘面数据
     */
    public static calcWinData(mapData: BetMap): WinData {
        let winData: WinData = new WinData();
        winData.add = mapData.multiple; // 每次盘面数据赢的分
        winData.freeGameVo = this.calcScatter(mapData);
        winData.isEnterFree = winData.freeGameVo.isEnterFree;
        winData.winLines = this.calcWinLine(mapData);
        winData.specialWinVo = this.calcSpecialWin(mapData);
        winData.featureGameVo = this.calcFeature(mapData);
        winData.isEnterFeature = winData.featureGameVo.isEnterFree;
        return winData;
    }

    /** 计算scatter中奖免费游戏 */
    private static calcScatter(mapData: BetMap): FreeGameVo {
        let freeGameVo: FreeGameVo = new FreeGameVo();
        let freeGameIndex: number[] = [];
        let freeGameIds: number[] = [];
        let winNum: number = 3;
        for (let i = 0; i < mapData.map.length; i++) {
            let tempIconId = mapData.map[i];
            if (GameDataDefine.isBelongsToFreeGame(tempIconId)) {
                freeGameIndex.push(i);
                freeGameIds.push(tempIconId);
            }
        }
        let freeGamelen = freeGameIds.length > 5 ? 5 : freeGameIds.length;
        if (freeGamelen >= winNum) {
            freeGameVo.freeId = freeGameIds[0];
            freeGameVo.isEnterFree = true;
            freeGameVo.add = this._iconConfigs[freeGameVo.freeId].odds[freeGamelen];
            freeGameVo.freeGameIndex = freeGameIndex;
            freeGameVo.freeGameIds = freeGameIds;
        }
        return freeGameVo;
    }

    /** 计算中奖线 lineData.line_id 中的所有线id*/ 
    private static calcWinLine(mapData: BetMap): WinLineVo[] {
        let winLines: WinLineVo[] = [];
        mapData.lines.forEach((lineData) => {
            let iconConf: IconConfig = this._iconConfigs[lineData.symbol];
            if(!iconConf){
                return;
            }
            let lineConf: LineConfig = this._lineConfigs[lineData.line_id];
            if(!lineConf){
                return;
            }
            let winItemIndexList: number[] = [];
            let winImgIdList: number[] = [];
            //计算中奖个数
            let continueIconCnt = 0;
            let haveWild = false;
            //中奖得图标
            let _symbols = [lineData.symbol];
            if(lineData.symbol == 101){
                _symbols = [1, 2, 3];
            }else if(lineData.symbol == 102){
                _symbols = [4, 5];
                // console.log("====calcWinLine==1=====calcWinLine====102=  ==", mapData);
            }
            // console.log("====calcWinLine==1=====calcWinLine====_symbols=  ==", _symbols);
            // console.log("====calcWinLine==1=====calcWinLine====lineData.symbol=  ==", lineData.symbol);
            // console.log("====calcWinLine==1=====calcWinLine====lineConf=  ==", lineData.line_id, lineConf);
            
            //默认左到右 icon：  1:777  2:77  3： ‘7’  4：‘bar5’5：‘bar’ 6：‘铃铛’ 7：‘樱桃’ 8：‘小恶魔’ 9：‘rapidhit’ 10：‘金币coin’11：‘心 scatter’101： ‘组合 123’102：‘组合 45’
            for (let iconIndex of lineConf.lineArray) {
                let _ishave = false;
                iconIndex = iconIndex - 1 // 本地数据是1--15 mapData.map 是 0 -- 14
                // 102的4、5 循环比对 线中的每一个值(iconIndex)在map中对应的值，如果有则认为存在。
                for (let i = 0; i < _symbols.length; i++) {
                    const _symbol = _symbols[i];
                    // console.log("====calcWinLine==1=====calcWinLine====_symbol=item  ==", _symbol);
                    if (mapData.map[iconIndex] == _symbol || GameDataDefine.isBelongsToWild(mapData.map[iconIndex])) {
                        _ishave = true;
                        // console.log("====calcWinLine==1=====calcWinLine====iconIndex=  ==", iconIndex, "_symbol =", _symbol, "i =", i);
                        break;
                    }
                }

                if(_ishave){
                    if (GameDataDefine.isBelongsToWild(mapData.map[iconIndex])) {
                        haveWild = true;
                    }
                    continueIconCnt++;
                    winItemIndexList.push(iconIndex);
                    winImgIdList.push(mapData.map[iconIndex]);
                }else{
                    break;
                }
            }

            
            // console.log("====calcWinLine==1=====calcWinLine====winItemIndexList=  ==", winItemIndexList);
            let resList = [];
            for (let i = 0; i < winImgIdList.length; i++) {
                let config = Config.getIconConfigByKey(winImgIdList[i]);
                resList.push(config.source_Normal);
            }
            let vo = {
                type: ROLL_BOTTOM_WIN_LINE_TYPE.FIR,
                lineId: lineData.line_id,
                resList: resList,
                iconWin: lineData.add
            }
            let winLineVo: WinLineVo = new WinLineVo();
            winLineVo.line = lineData.line_id;
            winLineVo.odd = iconConf.odds[continueIconCnt] * lineConf.rate;   //乘以线倍率 最终某条线的倍数
            winLineVo.add = lineData.add;   // 某条线总的赢的分数
            winLineVo.itemIndex = winItemIndexList;
            winLineVo.winImgId = lineData.symbol;
            winLineVo.itemImgId = winImgIdList;
            winLineVo.rollBottomWinLineVo = vo;
            winLineVo.haveWild = haveWild;
            winLines.push(winLineVo);
            // console.log("中奖线及分 continueIconCnt=", winLineVo.line, winLineVo.add, winLineVo.winImgId);
        });
        return winLines;
    }

