export class Resource<T extends Asset> {
    public path: string;
    public type: new () => T;
    public assets: T;

    constructor(path: string, type?: new () => T) {
        this.path = path;
        this.type = type;
    }
}

export class RES {
    /**bundle 资源根目录 */
    public static bundleName = "320000001";

    public static resConfig = {
        IconConfig: new Resource("resources/config/IconConfigs", JsonAsset),
        LineConfig: new Resource("resources/config/LineConfigs", JsonAsset),
        // BigWinAtlas: new Resource("resources/atlas/main/bigWin/atlas", SpriteAtlas),
        // bigSke: new Resource("resources/atlas/main/efffect/Bigwin/Bigwin", sp.SkeletonData),
    }

    private static _bundle: AssetManager.Bundle;

    public static get bundle() {
        return this._bundle;
    }

    public static init() {
        this._bundle = BundleManager.getInstance().getBundle(RES.bundleName);
        Log.d(Config.logTag, this._bundle, RES.bundleName);
    }

    /**需要重新load Atlas */
    public static loadSources(call: Function, obj: any) {
        let keys: string[] = [];
        for (let key in this.resConfig) {
            keys.push(key);
        }
        function load() {
            let key = keys.shift();
            if (!key) {
                Log.d(Config.logTag, "load assets complete");
                if (call && obj) {
                    call.call(obj);
                }
                return;
            }
            let asset = RES.resConfig[key];
            Log.d(Config.logTag, `loading source: ${key}`);
            RES.bundle.load(asset.path, asset.type, load);
        }
        load();
    }

    public static getRes<T extends Asset>(res: string | Resource<T>, type?: new () => T) {
        if (res instanceof Resource) {
            if (res.assets == null) {
                res.assets = this.bundle.get(res.path, res.type);
            }
            return res.assets;
        }

        return this.bundle.get(res, type);
    }

    /**
     * 获取其他bundle资源
     * @param res 资源路径
     * @param bundleName bundle名
     * @param type 资源类型
     * @returns 
     */
    public static getResInOther<T extends Asset>(res: string, bundleName: string, type?: new () => T) {
        let bundle = BundleManager.getInstance().getBundle(bundleName);
        if (bundle) {
            return bundle.get(res, type);
        }
        return null;
    }

    public static destroy() {
        // this._bundle.releaseAll();
        this._bundle = null;
        // this.bundleName = null;
        // this.resConfig = null;
        for (let key in this.resConfig) {
            let config = this.resConfig[key];
            config.assets = null;
        }
    }
}