    private getOrAddUIOpacity(node: Node): UIOpacity {
        let opacity = node.getComponent(UIOpacity);
        if (!opacity) {
            opacity = node.addComponent(UIOpacity);
        }
        return opacity;
    }

    private fadeIn(node: Node) {
        const opacity = this.getOrAddUIOpacity(node);
        opacity.opacity = 0;
        tween(opacity)
            .to(0.3, { opacity: 255 })
            .start();
    }

    private fadeOut(node: Node) {
        const opacity = this.getOrAddUIOpacity(node);
        tween(opacity)
            .to(0.3, { opacity: 0 })
            .call(() => {
                node.active = false;
            })
            .start();
    }

