    /**
     * 设置押注索引
     * @param betIndex 索引
     */
    public setBetIndex(betIndex: number) {
        let betCount = GameCommonModel.getInstance().betList.length;
        if (betCount <= 0) {
            Log.e("bet list count is zero");
            return;
        }
        if (betIndex < 0) {
            betIndex = betCount - 1;
        }
        if (betIndex >= betCount) {
            betIndex = 0;
        }

        GameCommonModel.getInstance().curBetIndex = betIndex;
        this.updateBet();
    }

    // 计算总押注值
    public updateBet() {
        let curBet = GameCommonModel.getInstance().curBet;
        console.log("====feature===updateBet==1=========curBet= i ==", GameCommonModel.getInstance().curBet);
        let line = this.model.curBetLine;
        let bet = curBet * line * this.model.betRate; // 4W * 30 * 1
        let score = GamesData.formatScore(bet, false); // bet/100W 返回 1.2
        // let buyScore = GamesData.formatScore(bet * Config.buyGaneBet, false);
        this.lab_bet.string = score;
        // if(this.lab_buy)
        //     this.lab_buy.string = buyScore;
        let money = GameCommonModel.getInstance().money;

        if (this.btn_buyGame) {
            if (money < bet * Config.buyGaneBet) {
                this.btn_buyGame.interactable = false;
            } else {
                this.btn_buyGame.interactable = true;
            }
        }

        console.log("=====updateBet==curBet= i ==", GameCommonModel.getInstance().curBet, ", bet = ", bet, ", score = ", score, ", betRate = ", this.model.betRate);
        console.log("updateBet curBet ==", curBet, "bet ==", bet, "line ==", line, "score ==", score);
        this.setRapidhitLvData(score);
    }
    
    private setRapidhitLvData(score){
        for (let i = 0; i < 6; i++) {
            let value = GameDataDefine.rapidhitDefine[i];
            let curData = GameDataDefine.rapidhitLvData[i];
            curData.reward = value.reward * score
        }
    }
    
    /**
     * 设置压线数组
     * @param array 线数组
     */
    public setLineArray(array: number[]) {
        if (!(array instanceof Array)) {
            Log.e("设置压线数组有误");
            return;
        }
        this._lineArray = array;
        if (array.length > 1) {
            this._canChangeLine = true;
        }
        else {
            this._canChangeLine = false;
        }
    }

    /**
     * 设置压线索引
     * @param index 线索引
     */
    public setLineIndex(index: number) {
        let lineCount = this._lineArray.length;
        if (lineCount <= 0) {
            Log.e("bet line count is zero");
            return;
        }
        if (index < 0) {
            index = lineCount - 1;
        }
        if (index >= lineCount) {
            index = 0;
        }
        this._curLineIndex = index;
        let curLine = this._lineArray[this._curLineIndex];
        this.model.curBetLine = curLine;
        this.updateBet();
    }

    /**
    * 修正押注
    * @param betIndex 押注索引
    */
    protected _adjustBet(betIndex: number, money: number) {
        let betList = GameCommonModel.getInstance().betList;
        let line = this.model.curBetLine;
        while (true) {
            let bet = betList[betIndex] * line * this.model.betRate;
            if (bet <= money) {
                break;
            }
            betIndex--;

            if (betIndex <= 0) {
                betIndex = 0;
                break;
            }
        }

        let subState = true;
        if (betIndex <= 0) {
            subState = false;
        }

        let addState = true;
        let nextIndex = betIndex + 1;
        if (nextIndex == betList.length || (betList[nextIndex] * line * this.model.betRate) >= money) {
            addState = false;
        }

        return { betIndex: betIndex, subState: subState, addState: addState };
    }

