    protected _addEvent() {
        this.btn_start.touchEndedFun = this.onStart.bind(this);
        this.btn_stop.touchEndedFun = this.onStop.bind(this);        

        this.btn_autostart.getComponent(UIButton).touchEndedFun = this.onAutoStart.bind(this);
        this.btn_autostartdown.getComponent(UIButton).touchEndedFun = this.onAutoStop.bind(this);

        if (this.btn_bet_add) {
            this.btn_bet_add.touchEndedFun = this.onBetClick.bind(this);
        }
        if (this.btn_bet_dec) {
            this.btn_bet_dec.touchEndedFun = this.onBetClick.bind(this);
        }
        if (this.btn_buyGame) {
            this.btn_buyGame.touchEndedFun = this.onBuyGame.bind(this);
        }

        if (this.btn_menu) {
            this.btn_menu.touchEndedFun = this.onMenu.bind(this);
        }
        if (this.helpBtn) {
            this.helpBtn.touchEndedFun = this.onHelp.bind(this);
        }
        if (this.soundBtn) {
            this.soundBtn.touchEndedFun = this.onSound.bind(this);
        }

        this.model.mainViewAddMoneyFun = this.addMoney.bind(this);

        //协议
        Eventer.getInstance().on(GameEventType.RollStart, this.closeAutoMenuNode, this);
        Eventer.getInstance().on(GameEventType.RollStop, this.closeAutoMenuNode, this);
        Eventer.getInstance().on(GameEventType.RollChangeLine, this.closeAutoMenuNode, this);
        Eventer.getInstance().on(GameEventType.RollChageBet, this.closeAutoMenuNode, this);
        Eventer.getInstance().on(GameEventType.RollQuick, this.closeAutoMenuNode, this);
        Eventer.getInstance().on(GameEventType.RollBackgroundClick, this.closeAutoMenuNode, this);
        Eventer.getInstance().on(GameEventType.RollMenuViewOpen, this.closeAutoMenuNode, this);
        Eventer.getInstance().on(GameEventType.RollMenuViewClose, this.closeAutoMenuNode, this);
        Eventer.getInstance().on(GameEventType.OnReceiveBalance, this._updateBalance, this);
    }

    protected removeFromStage() {
        Eventer.getInstance().offName(GameEventType.RollStart, this);
        Eventer.getInstance().offName(GameEventType.RollStop, this);
        Eventer.getInstance().offName(GameEventType.RollChangeLine, this);
        Eventer.getInstance().offName(GameEventType.RollChageBet, this);
        Eventer.getInstance().offName(GameEventType.RollQuick, this);
        Eventer.getInstance().offName(GameEventType.RollBackgroundClick, this);
        Eventer.getInstance().offName(GameEventType.RollMenuViewOpen, this);
        Eventer.getInstance().offName(GameEventType.RollMenuViewClose, this);
        Eventer.getInstance().offName(GameEventType.OnReceiveBalance, this);        

        let mLanguage: string = GamesData.getGameLanguageStr();
        let path = `resources/texture/language/${mLanguage}/languageTexture/GAMEWIN/spriteFrame`;
        if (this.gameWinTitle && this.gameWinTitle.spriteFrame) {
            this.gameWinTitle.spriteFrame.decRef();
            this.gameWinTitle.spriteFrame = null;
        }
        CacheManager.getInstance().remove(BUNDLE_NAME.rollCommon, path);

        path = `resources/texture/language/${mLanguage}/languageTexture/yue/spriteFrame`;
        if (this.moneyTitle && this.moneyTitle.spriteFrame) {
            this.moneyTitle.spriteFrame.decRef();
            this.moneyTitle.spriteFrame = null;
        }
        CacheManager.getInstance().remove(BUNDLE_NAME.rollCommon, path);

        this.model.mainViewAddMoneyFun = null;
    }

    private readonly _showPoint: Vec3 = new Vec3(234, -86, 0);
    private readonly _hidePoint: Vec3 = new Vec3(234, -486, 0);
    /**
    * 显示菜单
    * @param isShow 是否显示
    * @param hasTween 是否动画
    */
    private _showMenu(isShow: boolean, hasTween: boolean) {
        let point = this._hidePoint;
        let easeTyhpe: TweenEasing = "circIn";

        if (isShow) {
            point = this._showPoint;
            this.menuNode.active = true;
            easeTyhpe = "circOut";
        }
        if (hasTween) {
            Tween.stopAllByTarget(this.menuNode);
            let tween = new Tween(this.menuNode);
            tween = tween.to(0.3, { position: point }, { easing: easeTyhpe });
            tween = tween.call(() => { this.menuNode.active = isShow });  //隐藏组件，防止穿透
            tween.start();
        }
        // else {
        //     if (this.menuNode) {
        //         this.menuNode.setPosition(point);
        //         this.menuNode.active = isShow;
        //     }
        // }
    }

