    public stopMoveFreeImgTimer() {  
        if (this.moveFreeTipAct) {
            this.moveFreeTipAct.stop();
            this.moveFreeTipAct = null;
        }
        
        if (this.moveFeatureTipAct) {
            this.moveFeatureTipAct.stop();
            this.moveFeatureTipAct = null;
        }

        if (this.moveFeature2TipAct) {
            this.moveFeature2TipAct.stop();
            this.moveFeature2TipAct = null;
        }        
    }

    public moveFreeImage() {   
        this.featureTip.active = false;  
        this.feature2Tip.active = false;
        this.curWinNode.active = false;
        this.tipsNode.active = true;
        // 创建左移动画
        this.freeTip.active = true;
        this.freeTip.setPosition(new Vec3(50, 0, 0));
        let topX = -650;
        let TIME1 = 2;
        let TIME2 = 5;         
        let act1 = tween(this.freeTip)
            .delay(TIME1);  

        this.stopMoveFreeImgTimer();

        this.moveFreeTipAct = tween(this.freeTip)
            .to(TIME2, { 
                position: new Vec3(topX, 0, 0) 
            }) 
            .call(() => {
                this.freeTip.setPosition(new Vec3(50, 0, 0));
                this.freeTip.active = false;
                if (this.moveFreeTipAct) {
                    // 动画完成后更换图片
                    this.moveFeatureImage();
                    this.moveFreeTipAct.stop();
                }
            })

        tween(this.freeTip).sequence(act1, this.moveFreeTipAct).start();
    }

    public moveFeatureImage() {
        // 更换图片
        this.featureTip.active = true;
        this.featureTip.setPosition(new Vec3(50, 0, 0));
        let topX = -650;
        let TIME1 = 2;
        let TIME2 = 5;        
        
        if (this.moveFeatureTipAct) {
            this.moveFeatureTipAct.stop();
            this.moveFeatureTipAct = null;
        }

        let act1 = tween(this.featureTip)
            .delay(TIME1);  

        this.moveFeatureTipAct = tween(this.featureTip)
            .to(TIME2, { 
                position: new Vec3(topX, 0, 0) 
            }) 
            .call(() => {
                this.featureTip.setPosition(new Vec3(50, 0, 0));
                this.featureTip.active = false;
                if (this.moveFeatureTipAct) {
                    // 动画完成后更换图片
                    this.moveFeature2Image();
                }
            })

        tween(this.featureTip).sequence(act1, this.moveFeatureTipAct).start();
    }

    public moveFeature2Image() {
        // 更换图片
        this.feature2Tip.active = true;
        this.feature2Tip.setPosition(new Vec3(95, 5, 0));
        let topX = -650;
        let TIME1 = 2;
        let TIME2 = 5;        
        
        if (this.moveFeature2TipAct) {
            this.moveFeature2TipAct.stop();
            this.moveFeature2TipAct = null;
        }

        let act1 = tween(this.feature2Tip)
            .delay(TIME1);  

        this.moveFeature2TipAct = tween(this.feature2Tip)
            .to(TIME2, { 
                position: new Vec3(topX, 0, 0) 
            }) 
            .call(() => {
                this.feature2Tip.setPosition(new Vec3(95, 5, 0));
                this.feature2Tip.active = false;
                if (this.moveFeature2TipAct) {
                    // 动画完成后更换图片
                    this.moveFreeImage();
                }
            })

        tween(this.feature2Tip).sequence(act1, this.moveFeature2TipAct).start();
    }

