import { _decorator, Node, NodeEventType, AudioSource, UIOpacity, tween } from 'cc';
import AudioManager from '../../../../../scripts/framework/manager/AudioManager';
import { UIView } from '../../../../../scripts/framework/ui/UIView';
import GamesData from '../../../../gamesCommon/script/GamesData';
import { Eventer } from '../../../../../scripts/framework/Eventer';
import { RollValue } from '../../../../rollCommon/script/views/RollValue';
import LogUtil from "../../../../../scripts/common/utils/LogUtil";

const { ccclass, property } = _decorator;

@ccclass('GameModelResult')
export class GameModelResult extends UIView {

    @property(Node)
    private touchNode: Node;
    @property(Node)
    private freeContent: Node;
    @property(Node)
    private featureContent: Node;
    @property(Node)
    private freeDesc: Node;
    @property(Node)
    private featureDesc: Node;
    @property(Node)
    private resultBackground: Node;
    @property(Node)
    private resultContent: Node;
    @property(RollValue)
    private winLab: RollValue;
    
    private _data;
    private _audioSource: AudioSource = null!;

    private _isTouch: boolean = true;
    
    private RESULT_TIME = 1.5; //结算界面结束时遮罩淡隐时间
    init(...args): void {
        this._data = args[0];
    }

    start() {
        if(this._data.gameModel == 0){
            this.freeDesc.active = true;
            this.featureDesc.active = false;
            this.freeContent.active = true;
            this.featureContent.active = false;
        }else{
            this.freeDesc.active = false;
            this.featureDesc.active = true;
            this.freeContent.active = false;
            this.featureContent.active = true;
        }

        LogUtil.debug("=======Win==1 type====this._data.win=========", this._data.win);
        this.winLab.addValueTo(this._data.win);
        this.touchNode.on(NodeEventType.TOUCH_END, this.onTouch, this);
    }
    private onTouch() {
        if (this._isTouch) {
            if (this._data.call && this._data.thisObj) {
                this._data.call.call(this._data.thisObj);
            }
            this._isTouch = false;
            this._hide();
        }
    }

    protected onDestroy(): void {
    }

    private _hide() {
        if (AudioManager.Instance().musicEnabled) {
            GamesData.playMusic();
        }
        // if (this._audioSource) {
        //     this._audioSource.stop();
        //     this._audioSource.destroy();
        //     this._audioSource = null;
        // }
        // Eventer.getInstance().emit("BgSource");

        this.resultContent.active = false;
        this.resultBackground.active = false;
        let mask = this.node.getChildByName("mask");
        let opa = mask.getComponent(UIOpacity);
        opa.opacity = 255;
        
        tween(opa)
        .to(this.RESULT_TIME, {opacity:100})
        .delay(0.3)
        .call(()=> {
            
            opa.opacity = 220;
            this.close();
        })
        .start();

    }
}

