import {
  _decorator,
  Node,
  sp,
  NodeEventType,
  AudioClip,
  AudioSource,
  Vec3,
  Mask,
  Graphics,
  Color,
  UITransform,
  view,
} from "cc";
import AudioManager from "../../../../../scripts/framework/manager/AudioManager";
import { ResManager } from "../../../../../scripts/framework/manager/ResManager";
import { ScreenType, UIView } from "../../../../../scripts/framework/ui/UIView";
import GamesData from "../../../../gamesCommon/script/GamesData";
import {
  BigWinViewData,
  BigWinType,
} from "../../../../rollCommon/script/RollCommonModel";
import { RollValue } from "../../../../rollCommon/script/views/RollValue";
import { Config } from "../../Config";
import { Utils } from "../../utils/Utils";
import { Global } from "../../../../../scripts/main/Global";
import { Eventer } from "../../../../../scripts/framework/Eventer";
import { GameEventType } from "../../../../gamesCommon/script/GameEventType";

const { ccclass, property } = _decorator;

@ccclass("WinController")
export class WinController extends UIView {
  @property(Node)
  private touchNode: Node;
  @property(RollValue)
  private lab_bigWin: RollValue;
  @property(sp.Skeleton)
  private ske_bigwin: sp.Skeleton;
  @property(sp.Skeleton)
  private ske_g: sp.Skeleton;
  @property(sp.Skeleton)
  private ske_coin: sp.Skeleton;
  @property(Node)
  private rollNode: Node;
  private _data: BigWinViewData;
  private _audioSource: AudioSource = null!;
  private _playBigWinArr = [
    BigWinType.BIG_WIN,
    BigWinType.SUPER_WIN,
    BigWinType.EPIC_WIN,
    BigWinType.MEGA_WIN,
    BigWinType.ULTRA_BIG_WIN,
  ];

  private _endIndex: number;
  private _isTouch: boolean = true;
  @property(Node)
  private maskNode: Node;

  init(...args): void {
    this._data = args[0].bigdata;
  }

  start() {
    this._endIndex = this._playBigWinArr.indexOf(this._data.type);
    this._isTouch = true;

    let COIN_TIME = 2000;       //正常展示BigWin 时金币跳动的时间
    let COIN_TIME_AUTO = 1000;  //Auto展示BigWin 时金币跳动的时间
    let HIDE_TIME = 1000;       //展示BigWin 多久后自动关闭的时间
    let rollValue = this._data.value; //this.getRollValue();
    let initValue = this._data.value > rollValue ? rollValue : this._data.value;
    let delay = this._data.autoHide?COIN_TIME_AUTO:COIN_TIME;
    // 数字跳动动画
    this.lab_bigWin.addValueTo(initValue, true, delay);
    
    setTimeout(()=> {
      if (this._isTouch) {
        this._isTouch = false;
        this._hideSke();
      }
    }, delay + HIDE_TIME)

    this.touchNode.on(NodeEventType.TOUCH_END, this.onTouch, this);

    this._audioSource = this.node.getComponent(AudioSource)!;

    if (AudioManager.Instance().musicEnabled) {
      GamesData.stopBgMusic();
      if (!this._audioSource) {
        this._audioSource = this.node.addComponent(AudioSource)!;
        this._audioSource.playOnAwake = false;
        this._audioSource.loop = true;
      }
    }

    Utils.playMusic(Config.sounds[30]);
    this._showSkeleton();

    // 确保mask组件存在
    if (this.maskNode && !this.maskNode.getComponent(Mask)) {
      this.maskNode.addComponent(Mask);
    }

    this.onScreenSwitch();
    Eventer.getInstance().on(
      GameEventType.ScreenSwitch,
      this.onScreenSwitch,
      this
    );
  }

  // 播放Big Win 骨骼动画
  private _showSkeleton() {
    this.ske_coin.node.active = false;
    this.ske_g.node.active = false;
    this.ske_bigwin.node.active = false;
    let source;
    let typeName: string = this._playBigWinArr[this._endIndex];
    let coinSkin: string = "3-superb";

    switch (typeName) {
      case BigWinType.BIG_WIN:
        this.ske_bigwin.setSkin("big");
        source = Config.bigWinSounds[0];
        coinSkin = "1-nice";
        break;
      case BigWinType.SUPER_WIN:
        this.ske_bigwin.setSkin("super");
        source = Config.bigWinSounds[1];
        coinSkin = "2-mega";
        break;
      case BigWinType.EPIC_WIN: //"ultra-big-win":
        this.ske_bigwin.setSkin("epic");
        source = Config.bigWinSounds[2];
        coinSkin = "2-mega";
        break;
      case BigWinType.MEGA_WIN:
        this.ske_bigwin.setSkin("mega");
        source = Config.bigWinSounds[3];
        coinSkin = "3-superb";
        break;
      case BigWinType.ULTRA_BIG_WIN:
        this.ske_bigwin.setSkin("uitra");
        source = Config.bigWinSounds[4];
        coinSkin = "3-superb";
        break;

      default:
        break;
    }
    
    // 临时屏蔽
    // Utils.playBigWinSound(source);
    this.ske_bigwin.node.active = true;
    this.ske_bigwin.setAnimation(0, "appear", false);
    this.ske_bigwin.addAnimation(0, "loop", true);

    this.ske_g.node.active = true;
    this.ske_g.setAnimation(0, "appear", false);
    this.ske_g.addAnimation(0, "loop", true);

    this.ske_coin.node.active = true;
    this.ske_coin.setSkin(coinSkin);
    this.ske_coin.setAnimation(0, "appear", false);
    this.ske_coin.addAnimation(0, "loop", true);
  }

  private _hideSke(): void {
    this._hide();
  }

  private onScreenSwitch(): void {
    const isLandscape = Global.gameScreenType == ScreenType.Landscape;
    let scale = isLandscape ? 1 : 0.75;
    this.rollNode.setScale(new Vec3(scale, scale, scale));

    console.log("onScreenSwitch: isLandscape", isLandscape, this.maskNode);
    // 处理mask逻辑
    if (this.maskNode) {
      const maskComponent = this.maskNode.getComponent(Mask);
      const uiTransform = this.maskNode.getComponent(UITransform);
      if (maskComponent && uiTransform) {
        // 获取可见区域大小
        const visibleSize = view.getVisibleSize();
        let maskWidth, maskHeight;

        if (isLandscape) {
          // 横屏时，保持 720:1280 的比例，使用屏幕高度来计算宽度
          maskHeight = visibleSize.height;
          maskWidth = (maskHeight / 1280) * 720;
        } else {
          // 竖屏时，直接使用可见区域尺寸
          maskWidth = visibleSize.width;
          maskHeight = visibleSize.height;
        }

        // 设置mask大小
        uiTransform.setContentSize(maskWidth, maskHeight);

        // 确保mask节点位于中心
        this.maskNode.setPosition(0, 0);

        // 打印mask节点的信息
        console.log("Visible size:", visibleSize);
        console.log("Mask node size:", uiTransform.contentSize);
        console.log("Mask node position:", this.maskNode.position);

        // 为了便于测试，设置mask节点的颜色（半透明红色）
        const graphics =
          this.maskNode.getComponent(Graphics) ||
          this.maskNode.addComponent(Graphics);
        graphics.clear();
        graphics.fillColor = new Color(255, 0, 0, 128);
        graphics.rect(-maskWidth / 2, -maskHeight / 2, maskWidth, maskHeight);
        graphics.fill();
      }
    }
  }

  private playWinBg(source): void {
    if (AudioManager.Instance().musicEnabled) {
      ResManager.Instance().load(
        Global.gameId + "",
        Utils.getRollCommonSound(source),
        AudioClip,
        () => {},
        (evt: any) => {
          if (this._audioSource) {
            let clip: any = evt.data;
            this._audioSource.stop();
            this._audioSource.clip = clip;
            this._audioSource.play();
          }
        }
      );
    }
  }

  private onTouch() {
    if (this._isTouch) {
      this._isTouch = false;
      this.touchNode.off(NodeEventType.TOUCH_END, this.onTouch, this); //防止隐藏过程中再次点击
      this._hideSke();
    }
  }

  protected onDestroy(): void {    
    if (this._data.call && this._data.thisObj) {
      this._data.call.call(this._data.thisObj, this._data.type, this._data.value);
    }
    Eventer.getInstance().offName(GameEventType.ScreenSwitch, this);
  }

  private _hide() {
    if (this.ske_coin) {
      Utils.playSound(Config.sounds[31]);
      this.ske_coin.node.active = false;
      this.ske_coin.setAnimation(0, "disappear", false);
      this.lab_bigWin.node.active = false;
      
      this.ske_g.setAnimation(0, "disappear", false);

      this.ske_bigwin.setAnimation(0, "disappear", false);
      this.ske_bigwin.setCompleteListener(() => {
        if (AudioManager.Instance().musicEnabled) {
          GamesData.playMusic();
        }

        if (this._audioSource) {
          this._audioSource.stop();
          this._audioSource.destroy();
          this._audioSource = null;
        }

        Eventer.getInstance().emit("BgSource");
        Eventer.getInstance().offName(GameEventType.ScreenSwitch, this);
        this.close();
      });
    }
  }
}
