    public registerMsgMap() {
        this.socket.registerMsgListener<S2C_ProtocolParams<SlotBetVo_s2c>>(Protocol.SLOTBET, this._s2cSlotBet, this);
        this.socket.registerMsgListener<S2C_ProtocolParams<LastMap>>(Protocol.LASTMAP, this._s2cFreeSpin, this);
        this.socket.registerMsgListener<S2C_ProtocolParams<SlotBetVo_s2c>>(Protocol.SLOT_BUY, this._s2cSlotBet, this);
    }

    public destroy() {
        this._baseMap = null;
        this._specialMap = null;
        this._coupleMap = null;
        this._freeTimes = null;
        this.socket.unregisterMsgListener(Protocol.SLOTBET, this);
    }
    /**
     * 发送数据包
     * @param code 协议编码
     * @param msg json格式数据包，服务端解析有顺序，注意参数顺序
     * @returns 
     */
    public sendPack(code: string, msg: any) {
        this.socket.sendMessage<C2S_ProtocolParams>(code, msg);
    }

    /**
      * 购买免费
      * @param msg 单线押注数量
      */
    public c2sSlotBuy(msg: SlotBetVo_c2s) {
        let msgObj: C2S_ProtocolParams<SlotBetVo_c2s> = {
            type: Protocol.SLOT_BUY,
            message: msg
        }

        this.sendPack(Protocol.SLOT_BUY, msgObj);
    }

