    /* 初始化BaseData */
    public initBaseMap(message) {
        for (var baseData of message.base) { 
            baseData.coin = [];           
            for (let index = 0; index < baseData.map.length; index++) {
                if(baseData.map[index] == 10){
                    if (baseData.lines && baseData.lines) {
                        let linesArray = baseData.lines;
                        let isHave = false;
                        for (let i = 0; i < linesArray.length; i++) {
                            if (linesArray[i].add - 1 == index) {
                                baseData.coin[index] = linesArray[i].rate / 1000000;
                                isHave = true;
                                break;
                            }
                        }

                        if (!isHave) {
                            baseData.coin[index] = GameUtils.randomInt(1, 8);  
                        }
                    }
                    else {
                        baseData.coin[index] = GameUtils.randomInt(1, 8);  
                    }                  
                }            
            }
            this._baseMap.push(baseData);
        }
    }

    /* 初始化FreeTimes */
    public initFreeTimes(message) {
        let freeLen = message.free.length;
        let featrueLen = this._featureMap.length;
        
        this._freeTimes = [];
        this._freeTimes.push(freeLen - featrueLen);
    }
    
    /* 初始化FeatureMap */
    public isFeatureForFree(freeData) {
        let state = false;
        let map = freeData.map;
        let count = 0;
        for (let i = 0; i < map.length; i++) {
            if (map[i] == 9 || map[i] == 10) {
                count ++;
            }
        }

        if (count >= 6) {
            state = true;
        }

        return state;
    }

    /* 初始化FeatureMap */
    public initFeatureMap(message) {
        this._featureMap = message.feature;
        console.log("==ServerProxy== initFeatureMap 00 Feature牌面数据返回=>", this._featureMap, message.free.length);
        if (message.free.length > 0) {
            let count = 0;
            let isFeature = false;
            for (let index = 0; index < message.free.length; index++) {
                let element = message.free[index];
                count ++;
                if (!isFeature) {
                    isFeature = this.isFeatureForFree(element);    
                    this._featureBaseMap = element;
                    console.log("==ServerProxy== initFeatureMap 11 element =>", element, "isFeature = ", isFeature);
                }
                else {
                    this._featureMap.push(element);
                    console.log("==ServerProxy== initFeatureMap 22 =>", this._featureMap, isFeature);
                    if (element.multiple > 0) {
                        this._featureReward = element.multiple;
                        console.log("==ServerProxy== initFeatureMap _featureReward = ", this._featureReward);
                        break;
                    }
                }
            }
            console.log("==ServerProxy== initFeatureMap 33 Feature牌面数据返回=>", this._featureMap);
        }
    }

    // Free时获取的数据
    private freeAddCoin(message) {
        for (var free of message.free) { 
            free.coin = [];           
            for (let index = 0; index < free.map.length; index++) {
                if(free.map[index] == 10){
                    if (free.lines && free.lines) {
                        let linesArray = free.lines;
                        let isHave = false;
                        for (let i = 0; i < linesArray.length; i++) {
                            if (linesArray[i].add - 1 == index) {
                                free.coin[index] = linesArray[i].rate / 1000000;
                                isHave = true;
                                break;
                            }
                        }

                        if (!isHave) {
                            free.coin[index] = GameUtils.randomInt(1, 8);  
                        }
                    }
                    else {
                        free.coin[index] = GameUtils.randomInt(1, 8);  
                    }                  
                }            
            }
            this._baseMap.push(free);
        }
    }

    public getRecovery() {
        return this._recovery;
    }

    public getMapLenght(): number {
        return this._baseMap.length;
    }

    
    /**取Free初始牌面值 */
    public getFreeBaseMap(): BetMap {
        return this._freeBaseMap;
    }

    /**取Feature初始牌面值 */
    public getFeatureBaseMap(): BetMap {
        return this._featureBaseMap;
    }

    /**取当前牌面值 */
    public getItemArray() {
        // if (mapType == MapType.BASE) {
        if (!this._baseMap || this._baseMap.length == 0) {
            return null;
        }
        let map = this._baseMap[0];
        console.log("ServerProxy getItemArray  this._baseMap=>", this._baseMap, "this.isFree = ", this.isFree);
        if (this.isFree){
            map = this._baseMap.shift();
        }
        this._featureInitMap = map.map.slice(0, map.map.length);
        return map;
    }

    public getFreeTimes() {
        if (!this._freeTimes || this._freeTimes.length == 0) {
            return 0;
        }
        console.log("ServerProxy getFreeTimes  this._freeTimes.length=>", this._freeTimes.length);
        return this._freeTimes.shift();
    }
    
    // Free时Feature的总赢分数
    public getFreeToFeatureReward() {
        return this._featureReward;
    }

    // 断线重连使用客户端计算出的值，否则使用_reward
    public getReward() {
        console.log("ServerProxy getReward _win=>",  this._win, "this._reward = ", this._reward);
        let reward = 0
        if (this._reward > 0) {
            reward = this._reward;
        }
        else {
            // if (this._win != -1) {
                if (this._featureMap && this._featureMap.length > 0) {
                    let length = this._featureMap.length - 1;
                    let multiple = this._featureMap[length].multiple;
                    reward = this._win + multiple;
                    console.log("getReward _reward=>", this._reward, "this._win = ", this._win, "multiple = ", multiple);
                }
                else if (this._freeMap && this._freeMap.length > 0) {
                    let length = this._freeMap.length;
                    let multipleSum = 0;
                    for (let index = 0; index < length; index++) {
                        let multiple = this._freeMap[index].multiple;
                        multipleSum = multipleSum + multiple
                    }

                    reward = this._win + multipleSum;
                    console.log("getReward _freeMap _reward=>", this._reward, "this._win = ", this._win, "multipleSum = ", multipleSum);
                }
                else {
                    reward = this._win;
                }
            // }
        }
        console.log("ServerProxy getReward _win=>",  this._win, "reward = ", reward);
        return reward;
    }  
    
