    public java2cPlayback(): any {
        // Log.d('Start Replay');
        Global.playbackFinish = false;
        let vo = GameUtils.copyTab(Global.playbackVo);
        this._baseMap = vo.gameRes.base;
        // this._freeMap = vo.gameRes.free;
        for (var baseData of vo.gameRes.free) {
            this._baseMap.push(baseData);
        }
        this._freeTimes = [];
        this._freeTimes.push(vo.gameRes.free.length);
        // Utils.event.emit(GameEventType.OnReceiveBet);
        return vo;
    }

