import { _decorator, Component, sys } from 'cc';
const { ccclass } = _decorator;

@ccclass('FullscreenScript')
export class FullscreenScript extends Component {
    // 调用全屏
    public static requestFullScreen(element: HTMLElement): void {
        if (element.requestFullscreen) {
            element.requestFullscreen();
        }
    }

    // 退出全屏
    public exitFullScreen(): void {
        if (document.exitFullscreen) {
            document.exitFullscreen();
        }
    }

    // 检查是否全屏
    isFullScreen(): boolean {
        return document.fullscreenElement ?
            true : false;
    }

    start() {
        // 获取canvas元素
        // const canvas = document.getElementById('GameCanvas') as HTMLCanvasElement;
        console.log("====onChangeFullScreen==== fullscreen  ==");
        document.addEventListener('keypress', (e: KeyboardEvent) => {
            if (e.key === 'Enter') {
              this.toggleFullScreen();
            }
          }, false);
    }

    public toggleFullScreen(isFull?:boolean) {
        if (!document.fullscreenElement) {
            console.log("====toggleFullScreen==== requestFullscreen  ==");
            document.documentElement.requestFullscreen();
        } else if (document.exitFullscreen) {
            // 如果是全屏则不执行退出全屏操作
            if (!isFull) {
                document.exitFullscreen();
            }
        }
    }

      
    onChangeFullScreen() {
        if (this.isFullScreen()) {
            const canvas = document.getElementById('GameCanvas') as HTMLCanvasElement;
            // this.requestFullScreen(canvas);
            console.log('Entered fullscreen');
        } else {
            console.log('Exited fullscreen');
        }
    }
}