import { _decorator, Component, Node, sp, tween, Tween, Prefab, instantiate, Vec3, Label } from 'cc';
import { Config, RES, Resource } from '../../Config';
import { Utils } from '../../utils/Utils';
import { Global } from '../../../../../scripts/main/Global';
import { MainView } from './MainView';
import { GameDataDefine, IconConfig, IconData, StopRollData } from '../../GameDataDefine';
import { Item } from './Item';
import { GameUtils } from '../../../../../scripts/common/utils/GameUtil';
import LogUtil from '../../../../../scripts/common/utils/LogUtil';
import { ResManager } from '../../../../../scripts/framework/manager/ResManager';
import GameDataManager from '../../GameDataManager';
import StorageUtil from '../../../../../scripts/common/utils/StorageUtil';
import { GameEventType } from '../../../../gamesCommon/script/GameEventType';
import { Eventer } from '../../../../../scripts/framework/Eventer';
import { Timer } from '../../utils/Timer';
import TimeUtil from '../../../../../scripts/common/utils/TimeUtil';
const { ccclass, property } = _decorator;

@ccclass('FeatureGameView')

export class FeatureGameView extends Component {
    private _group_items: Node;
    private _rollItems: RollItem[];
    private _colCount = 5;  //列数
    private _rowCount = 3;  //行数

    /**免费旋转3次节点 */
    private timesNode:Node;
    /**免费旋转3次 */
    private featureCount = 3;
    /**当前盘面所有的rapidhit，保存到本地，不管是否有播放 */
    private _rapidhitCountAnim = 0;
    
    /**盘面数据 */
    private _mapData: number[];
    private _mainView: MainView;
    /**当前盘面数据 */
    private mapInfo:number[][];

    private boxAnim:Node;

    /**最后三个时期待火 */
    private boxAnimArr = [];
    
    /**存储Feature所有数据 */
    private featureData = null;  
    private featureTimes = 0;
    private _isPlayRapidCount = 0; //本轮有播放多少个RapidHit
    
    /**全满就结束 */
    private featureFullEnd:boolean = false;

    /**停止元素动作 */
    public playIconEffectGroup:Node = null;

    /**遮罩 */
    public mask:Node = null;

    /**是否立即停止 */
    private _isStopRollNow: boolean;

    // 保存在playIconEffectGroup里的准备做特效的coin
    private coinPreArray = [];

    private START_ROLL_TIME = 0.04; //0.15
    private STOP_ONE_TIME = 0.4; //0.75
    private RAPID_DOWN_TIME = 300; //每次获取RapidHit时展示Down动画的时间
    private RAPID_FLY_TIME = 500; //每次获取RapidHit时展示飞动画的时间
    
    public init(mainView: MainView): void {
        this._mainView = mainView;
        this.node.active = false;

        this._group_items = this.node.getChildByName("group_items");

        this.boxAnim = this._group_items .getChildByName("effbox");
        this.boxAnim.active = false;

        this.timesNode = this._group_items.getChildByName("timesNode");

        this.playIconEffectGroup = this.node.getChildByName("win_effect");
        this.playIconEffectGroup.active = false;
        
        this.mask = this.playIconEffectGroup.getChildByName("mask");
        this.mask.active = false;

        this._isStopRollNow = false;
        this._rollItems = [];
        this.setFeatureGameTimes();
        Eventer.getInstance().on(GameEventType.nextRoll, this.nextStartRoll, this);
    }

    onDestroy(): void {
        // console.log("======FeatureGameView==1=========onDestroy ==");
        Eventer.getInstance().off(GameEventType.nextRoll);
    }
    
    // 每次调用Feature时都初始化所有使用数据
    public nextStartRoll(operate: boolean){
        if (operate) {             
            this._mainView._startRoll();
        }
    }


    // 每次调用Feature时都初始化所有使用数据
    public intoFeature(mapData, isForRecovery){
        this.mask = this.playIconEffectGroup.getChildByName("mask");
        this.mask.active = false;
        this.playIconEffectGroup.removeAllChildren();
        // 清理子节点后增加mask
        this.playIconEffectGroup.addChild(this.mask);

        this._group_items = null;
        
        this._group_items = this.node.getChildByName("group_items");

        this.boxAnim = this._group_items.getChildByName("effbox");
        this.boxAnim.active = false;

        this.timesNode = this._group_items.getChildByName("timesNode");
        
        this._mapData = [];
        this.featureData = mapData;
        this.featureCount = 3;
        this.featureTimes = 0;
        this.boxAnimArr = [];
        this.coinPreArray = [];
        this._isStopRollNow = false;
        
        if (!isForRecovery) {
            for (let i = 0; i < mapData.init_map.length; i++) {
                if (mapData.init_map[i] == 9) {
                    GameDataDefine.rapidhitCount++;
                }
            }
            
            StorageUtil.saveRapidhitCount(GameDataDefine.rapidhitCount.toString());
        }

        this.featureCount = Number(StorageUtil.getFeatureCount());
        // console.log("====feature===FeatureGameView==1=========StorageUtil ==", StorageUtil.getFeatureCount());
        GameDataDefine.rapidhitCount = Number(StorageUtil.getRapidhitCount());
        this._rapidhitCountAnim = GameDataDefine.rapidhitCount;

        // console.log("====feature===FeatureGameView==1=========_StorageUtil GameDataDefine.rapidhitCount ==", GameDataDefine.rapidhitCount);
        this.node.active = true;
        this.playIconEffectGroup.active = true;

        this.initMapData(mapData);
        this.setFeatureGameTimes();
    }

    // 展示FeatureGameView 的 所有icon图标
    private initMapData(mapData){
        this._rollItems = [];
        let _idx = 0;
        this.mapInfo = [];
        for (let i = 0; i < this._colCount; i++) {
            let _dd = []
            for (let j = 0; j < this._rowCount; j++) {
                _idx = i*this._rowCount+j;
                _dd.push(mapData.init_map[_idx]);
            }
            // _dd.reverse();
            this.mapInfo.push(_dd);
        }

        // LogUtil.debug("=======FeatureGameView==1= mapData============", mapData);
        let coinArray = []
        for (let index = 0; index < mapData.maps[0].lines.length; index++) {
            let lineArray = mapData.maps[0].lines[index];
            if (lineArray.symbol == 10){
                const element = (lineArray.add).toString();
                coinArray[element] = lineArray.rate;
            }
        }
        // this.setRandomState(true);
        
        // LogUtil.debug("=======FeatureGameView==1= coinArray============", coinArray);
        for (let i = 0; i < this._colCount; i++) {
            for (let j = 0; j < this._rowCount; j++) {
                let node = this._group_items.getChildByName(`ItemColumn${i}_${j}`);
                let index = i * this._rowCount + j;
                let item = new RollItem(node, index);

                // LogUtil.debug("=======FeatureGameView==1= index============", index, this.mapInfo[i][j]);
                
                item.init(this.mapInfo[i][j], coinArray[index.toString()], i, j);
                this._rollItems.push(item);
                if (GameDataDefine.isBelongsToFeatureGame(this.mapInfo[i][j])) {
                    let worldPos = item.node().worldPosition;
                    // 初始化进来播放动画
                    this._stopRapidCoinItem(worldPos, this.mapInfo[i][j], index);
                }
            }
        }
    }
    
    /**
     * 初始界面開始旋轉前播放Rapid Anim
     */
    public initPlayRapidSke() {
        let state = false;
        for (let i = 0; i < this._colCount; i++) {
            for (let j = 0; j < this._rowCount; j++) {  
                let index = i * this._rowCount + j;  
                let node = this._group_items.getChildByName(`ItemColumn${i}_${j}`);
                let item = new RollItem(node, index);            
                if (this.mapInfo[i][j] == 9) {    
                    state = true; 
                    item.node().active = false;
                    setTimeout(()=> {        
                        this._playRapidSke(index);
                    }, 200)
                    let worldPos = item.node().worldPosition;
                    // 初始化进来播放动画
                    this._playRapidItem(worldPos, this.mapInfo[i][j]);
                }
            }
        }

        return state;
    }

    /**
     * 初始界面開始旋轉前播放Rapid Anim
     */
    public _playRapidItem(pos, id){
        let path = "resources/prefabs/ui/CollectItem";
        ResManager.Instance().load(Global.gameId + "", path, Prefab, () => { }, (evt: any) => {
            let pre = instantiate(evt.data);
            this.playIconEffectGroup.addChild(pre);
            pre.setWorldPosition(pos);
            let _icon_ske = pre.getChildByName('icon_ske');
            let config = Config.getIconConfigByKey(id);
            let aniName = config.aniName;
            let valNode = _icon_ske.getChildByName("Node");
            pre.setScale(2, 2, 2);
            valNode.setScale(0.5, 0.5, 0.5);
            valNode.active = false;
   
            let path = config.path;
            if (path) {
                let ske = new Resource(path, sp.SkeletonData);
                let data = RES.getRes(ske, sp.SkeletonData);
                _icon_ske.setPosition(config.aniX, config.aniY);
                _icon_ske.active = true;
                _icon_ske.getComponent(sp.Skeleton).clearTrack(0);
                _icon_ske.getComponent(sp.Skeleton).setToSetupPose();
                _icon_ske.getComponent(sp.Skeleton).skeletonData = data;
                _icon_ske.getComponent(sp.Skeleton).loop = false;                
                _icon_ske.getComponent(sp.Skeleton).setAnimation(0, "fire", false);
                _icon_ske.getComponent(sp.Skeleton).setCompleteListener(()=>{
                    if(id == 9){
                        pre.active = false;
                        pre.removeFromParent();
                    }
                });                
            }
        });
    }

    public exitFeature(){
        Tween.stopAllByTarget(this.node);
        this.node.active = false;
         this.playIconEffectGroup.active = false;
         this.mask.active = false;
    }
    
    //设置feature下免费转动次数
    private setFeatureGameTimes(){
        for (let i = 0; i < 3; i++) {
            let timesNum = this.timesNode.getChildByName(`timesNum${i+1}`);
            if(this.featureCount >= i+1){
                timesNum.active = true;
            }else{
                timesNum.active = false;
            }
        }
        // this._freeGameNum = times;
        // this._freeGameTimes.getComponent(Label).string = this._freeGameNum.toString();
    }
    public updateFreeGameTimes(): void {
        if (this.featureCount > 0) {
            this.featureCount--;
            LogUtil.debug("=======FeatureGameView==1= saveFeatureCount============", this.featureCount);
            StorageUtil.saveFeatureCount(this.featureCount.toString())
        }
        this.setFeatureGameTimes();
    }
    /**
     * 转动
     * @param delta 
     */
    public updateRoll(delta: number): void {
        for (let i = 0; i < this._rollItems.length; i++) {
            const item = this._rollItems[i];
            item.update(delta);
        }
    }

    public showALLItem() {
        for (let item of this._rollItems) {
            item.showFrameAll();
        }
    }

    public hideItem(idx: number[]) {
        for (let item of this._rollItems) {
            item.showFrameAll();
        }
        for (let index of idx) {
            // let list = Math.floor(index / 3);
            // index = index % 3;
            // let item = this._rollItems[list];
            // if (item) {
            //     item.showFrameByIndex(index, false);
            // }
        }
    }

    public setImgSprite(idArr: number[]): void {

        for (let i = 0; i < idArr.length; i++) {
            let list = Math.floor(i / 3);
            let index = i % 3;
            //let item = this._rollItems[list][index];
            let item = this._rollItems[i];
            // console.log("list", list, index);
            if (item) {
                item.setImgSprite(index, idArr[i]);
            }
        }
    }

    /**
     * 获取rapid coin
     * @param map 
     * @returns 
     */
    private _getRapidCoinNum(map: number[]) {
        let rapidCoinNum = 0;
        for (let i = 0; i < map?.length; i++) {
            if (GameDataDefine.isBelongsToFeatureGame(map[i])) {
                rapidCoinNum++;
            }
        }
        return rapidCoinNum;
    }
    
    /**
     * 盘面中的元素停止特效
     * 1. 初始盘面时调用
     * 2. 每次旋转停止时调用
     */
    public _stopRapidCoinItem(pos, id, itemIdx, isStop?: boolean){
        let path = "resources/prefabs/ui/CollectItem";
        ResManager.Instance().load(Global.gameId + "", path, Prefab, () => { }, (evt: any) => {
            let pre = instantiate(evt.data);
            this.playIconEffectGroup.addChild(pre);
            pre.setWorldPosition(pos);
            let _icon_ske = pre.getChildByName('icon_ske');
            let config = Config.getIconConfigByKey(id);
            let aniName = config.aniName;
            let valNode = _icon_ske.getChildByName("Node");
            pre.setScale(2, 2, 2);
            valNode.setScale(0.5, 0.5, 0.5);
            valNode.active = false;
            // console.log("====feature===_onOneStop==1_stopRapidCoinItem itemIdx= ", itemIdx, "==id===", id, "==this.featureTimes===", this.featureTimes);
            if(id == 10){
                if (isStop) {
                    Utils.playSound(Config.sounds[18]);
                }

                this.coinPreArray[itemIdx] = pre;
                
                valNode.active = true;
                let val = valNode.getChildByName("valLab");
                let rate = GameDataManager.getFeatureCoinMap(this.featureTimes, itemIdx + 1);
                // console.log("====feature===_onOneStop==1_stopRapidCoinItem=========itemIdx===", itemIdx, "==rate===", rate);
                let coinVal = "0"
                if (rate != 0){
                    if (Number.isInteger(rate)) {
                        coinVal = `${rate}.00`;
                    }
                    else {
                        coinVal = rate.toString();
                    }
                }
                else {
                    // let id = GameUtils.roundFloat(GameUtils.randomFloat(1, 9), 2);
                    let id = GameUtils.randomInt(1, 10);
                    coinVal = `${id}.00`;
                }
                val.getComponent(Label).string = `${coinVal}`;

                // console.log("====feature===_onOneStop==1===========coinVal===", coinVal);
            }
            
            if(id == 9){
                aniName = "down";
                Utils.playSound(Config.sounds[19]);
            }

            let path = config.path;
            if (path) {
                let ske = new Resource(path, sp.SkeletonData);
                let data = RES.getRes(ske, sp.SkeletonData);
                _icon_ske.setPosition(config.aniX, config.aniY);
                _icon_ske.active = true;
                _icon_ske.getComponent(sp.Skeleton).clearTrack(0);
                _icon_ske.getComponent(sp.Skeleton).setToSetupPose();
                // console.log("====feature===SkeletonData==1===========data===", data);
                _icon_ske.getComponent(sp.Skeleton).skeletonData = data;
                _icon_ske.getComponent(sp.Skeleton).setAnimation(0, aniName, false);
                _icon_ske.getComponent(sp.Skeleton).loop = false;

                //只有每个停止时才有爆炸特效
                if(id == 9){
                    if (isStop) {
                        Timer.setTimeOut(this, () => {
                            _icon_ske.getComponent(sp.Skeleton).setAnimation(0, "fire", false);
                            _icon_ske.getComponent(sp.Skeleton).setCompleteListener(()=>{
                                if(id == 9){
                                    pre.active = false;
                                    pre.removeFromParent();
                                }
                            });
                        }, this.RAPID_DOWN_TIME);
                    }
                    else {
                        _icon_ske.getComponent(sp.Skeleton).setCompleteListener(()=>{
                            if(id == 9){
                                pre.active = false;
                                pre.removeFromParent();
                            }
                        });
                    }
                }
            }
        });
    }

    /**rapid收集特效拖尾
     * col 行
     * row 列
     */
    private _playRapidSke(_index): void {
        let worldPos = this._rollItems[_index].node().worldPosition;
        this._mainView._flyCollectRapidItem(worldPos);
    }
    
    /**coin收集特效
     * col 行
     * row 列
     */
    private _playCoinSke(): void {
        let coinIndexArray = []
        console.log("====setCoinValDouble===FeatureGameView==1=========this._mapData ==", this._mapData);
        for (let i = 0; i < this._mapData?.length; i++) {
            if(this._mapData[i] == 10) {                
                console.log("====setCoinValDouble===FeatureGameView==1=========_playCoinSke= i ==",i);
                coinIndexArray.push(i + 1);
                let worldPos = this._rollItems[i].node().worldPosition;
                if (!this.coinPreArray[i]) {
                    this.addCoidPreArray(worldPos, i)
                }
            }
        }

        let isNull = false;
        for (let index = 0; index < this.coinPreArray.length; index++) {
            if (!this.coinPreArray[index]) {
                isNull = true;
                break;
            }             
        }

        console.log("=====_stopRapidCoinItem setCoinValDouble= ", this.coinPreArray, "length = ", this.coinPreArray.length, "isNull", isNull);
        // 如果金币满了，15个则每个金币值翻倍
        if (this.coinPreArray && !isNull) {
            for (let index = 0; index < this.coinPreArray.length; index++) {
                console.log("====setCoinValDouble====00======i ==",index, "this.coinPreArray[index] = ", this.coinPreArray[index]);
                this.setCoinValDouble(this.coinPreArray[index])                
            }
        }

        this.mask.active = true; 
        this._mainView.collectCoinWin(this.node, coinIndexArray, this.coinPreArray);           
    }
    
    /**
     * 设置金币值翻倍
     */
    public setCoinValDouble(coinPre){ 
        if (coinPre) {
            let icon_ske = coinPre.getChildByName('icon_ske');
            let valNode = icon_ske.getChildByName("Node");
            let valLab = valNode.getChildByName("valLab");
            let val = Number(valLab.getComponent(Label).string) * 2;
            let valString = `${val}`
            if (Number.isInteger(val)) {
                valString = `${val}.00`;
            }

            valLab.getComponent(Label).string = valString;
        }
    }

    // 将所有获得的金币都放到coinPreArray
    public addCoidPreArray(pos, itemIdx){
        let path = "resources/prefabs/ui/CollectItem";
        ResManager.Instance().load(Global.gameId + "", path, Prefab, () => { }, (evt: any) => {
            // Utils.playSound(Config.sounds[18]);
            let pre = instantiate(evt.data);
            this.playIconEffectGroup.addChild(pre);
            pre.setWorldPosition(pos);
            let _icon_ske = pre.getChildByName('icon_ske');
            let valNode = _icon_ske.getChildByName("Node");
            pre.setScale(2, 2, 2);
            valNode.setScale(0.5, 0.5, 0.5);

            console.log("====feature===_onOneStop==1_stopRapidCoinItem itemIdx= ", itemIdx);
            this.coinPreArray[itemIdx] = pre;

            valNode.active = true;
            let val = valNode.getChildByName("valLab");
            let rate = GameDataManager.getFeatureCoinMap(0, itemIdx + 1);
            console.log("====feature===_onOneStop==1_stopRapidCoinItem=========itemIdx===", itemIdx, "==rate===", rate);
            let coinVal = "0"
            if (rate != 0){
                if (Number.isInteger(rate)) {
                    coinVal = `${rate}.00`;
                }
                else {
                    coinVal = rate.toString();
                }
            }
            else {
                // let id = GameUtils.roundFloat(GameUtils.randomFloat(1, 9), 2);
                let id = GameUtils.randomInt(1, 10);
                coinVal = `${id}.00`;
            }
            val.getComponent(Label).string = `${coinVal}`;

            console.log("====feature===_onOneStop==1===========coinVal===", coinVal);
        })
    }


    /**
     * 期待火焰框
     */
    private _playEffSke(pos:Vec3): void {
        let eff = instantiate(this.boxAnim);
        this._group_items.addChild(eff);
        eff.position = pos;
        eff.active = true;
        let effSke = eff.getComponent(sp.Skeleton);
        effSke.setAnimation(0, "1", true);
        this.boxAnimArr.push(eff);
    }

    /**
     * 开始滚动
     */
    public startRoll() {
        this._isStopRollNow = false;  
        let featureItems = [];
        let data = this.featureData.maps[this.featureTimes].map;
    
        // 计数用于断线重连 手动停止时不增加
        for (let index = 0; index < data.length; index++) {
            if (data[index] == 9) {
                this._rapidhitCountAnim ++
                StorageUtil.saveRapidhitCount(this._rapidhitCountAnim.toString());
            }            
        }
        
        console.log("====FeatureGamesetRollData==1==startRoll===开始旋转=this.featureTimes=", this.featureTimes, 
            "this.featureData.maps.length = ", this.featureData.maps.length, "GameDataDefine.rapidhitCount ==", GameDataDefine.rapidhitCount,
        "存储本地值this._rapidhitCountAnim=", this._rapidhitCountAnim);

        // if (this.mapInfo) {       
            for(let i = 0; i < this._colCount; i++){
                for (let j = this._rowCount-1; j >= 0; j--) {                    
                    //中了coin不转
                    if(this.mapInfo[i][j] == 10){
                    }else{
                        
                        let item = this._rollItems[i*this._rowCount+j];
                        featureItems.push(item);
                    }
                }
            }
            
            console.log("=====FeatureGameView==1=startRoll======featureItems===", featureItems);
            for (let i = 0; i < featureItems.length; i++) {
                const _itemObj = featureItems[i];
                tween(this.node)
                // .delay(this.START_ROLL_TIME * i)
                .call(()=>{
                    if (_itemObj) {
                        _itemObj.startRoll();   
                        //还剩三个以下空槽位的时候播放期待框特效
                        if(featureItems.length < 4){
                        // if(i > featureItems.length - 4){
                            this._playEffSke(_itemObj.node().position);
                        }
                    }
                }).start();
            }
        // }
    }

    /**
     * 设置盘面 并停止 从0,0 到3,5 延迟多少秒设置列停止
     * @param data 盘面数组
     * @param delay 延时设置
     */
    public setRollData(data: number[], delay?: number) {
        if(this.featureTimes >= this.featureData.maps.length){
            LogUtil.error("feature is complete");
            return
        }

        data = this.featureData.maps[this.featureTimes].map;

        if (delay == undefined) {
            delay = this.STOP_ONE_TIME;
        }
        else {
            this._isPlayRapidCount = 0
        }

        console.log("====_featureGameViewsetRollData==1==rapidhitCount = ", GameDataDefine.rapidhitCount, "_rapidhitCountAnim = ", this._rapidhitCountAnim);
        console.log("=======_featureGameViewsetRollData==1= _stopRollItem===featureTimes=========", this.featureTimes, "data = ", data);
        this._mapData = [];
        this._mapData.push(...data);

        let _timeCount = 0;
        // console.log("====_featureGameViewsetRollData==1========= setRollData 停止开始==", this.featureData.maps.length);
        for(let i = 0; i < this._colCount; i++){
            for(let j = 0; j < this._rowCount; j++){                
                let _idx = i * this._rowCount + j;
                let item = this._rollItems[_idx];
                
                // item._index
                Tween.stopAllByTarget(item);
                tween(item).delay(_timeCount * delay)
                .call(()=>{
                    //应该是每一个格子的数据
                    let stopRollData = new StopRollData();
                    let iconid = this._mapData[_idx] > 0?this._mapData[_idx]:GameUtils.randomInt(1, 8);
                    stopRollData.map = [iconid];
                    // console.log("===_featureGameViewsetRollData===getIndex====", item.getIndex(), "this._mapData[_idx] = ", this._mapData[_idx], "iconid = ", iconid);
                    item.stopRoll(this.isStopRollNow, stopRollData, this._onOneStop, this);
                })
                .start();

                if(!GameDataDefine.isNoRunToFeatureGame(this.mapInfo[i][j])){
                    _timeCount++
                    if(GameDataDefine.isNoRunToFeatureGame(this._mapData[_idx])){
                        this.mapInfo[i][j] = this._mapData[_idx];
                        // console.log("=======_featureGameViewsetRollData==1= _idx=====coin=======", _idx, this._mapData[_idx]);
                    }
                }
            }
        }

        /**判断是否满 */
        this.featureFullEnd = true;
        for (let i = 0; i < this._mapData.length; i++) {
            // console.log("=======setRollData==1= i=====coin=======", i, this._mapData[i]);
            if(this._mapData[i] <= 0){
                this.featureFullEnd = false;
            }
        }
    }   

    public get isStopRollNow(): boolean {
        return this._isStopRollNow;
    }

    /**
     * 立刻停止转动
     */
    public stopRollNow() {
        this._isStopRollNow = true;
    }

    public get allIsRoll(): boolean {
        let allRoll = false;
        for (let i = 0; i < this._colCount; i++) {
            for (let j = 0; j < this._rowCount; j++) {
                let item = this._rollItems[i * this._colCount + j];
                if (item && item.isRolling) {
                    allRoll = true;
                } else {
                    allRoll = false;
                    return allRoll;
                }
            }
        }
        return allRoll;
    }

    public setRandomState(is: boolean) {
        for (let i = 0; i < this._colCount; i++) {
            for (let j = 0; j < this._rowCount; j++) {
                let item = this._rollItems[i * this._colCount + j];
                if (item){
                    item.randomState = is;
                }
            }
        }
    }

    /**
     * 某一个位置列停止
     * @param col 列索引
     * @param row 行
     * @returns 
     */
    private _onOneStop(itemIdx:number) {
        if (GameDataDefine.isBelongsToFeatureGame(this._mapData[itemIdx])) {
            this.featureCount = 3
            StorageUtil.saveFeatureCount(this.featureCount.toString())
            this.setFeatureGameTimes();
            Utils.playSound(Config.sounds[11]);
            
            // 停止Rapid + 播放Rapid特效
            let worldPos = this._rollItems[itemIdx].node().worldPosition;
            this._stopRapidCoinItem(worldPos, this._mapData[itemIdx], itemIdx, true);
        }

        //收集特效
        if(this._mapData[itemIdx] == 9){
            this._isPlayRapidCount ++;            
            GameDataDefine.rapidhitCount++;
            
            Timer.setTimeOut(this, () => {
                let img = this._rollItems[itemIdx];
                img.node().active = false;
                // img.node().getComponent(Item);
                //飞向rapid位置
                this._playRapidSke(itemIdx);
                // console.log(itemIdx+"====feature===_onOneStop=====_mapData=========",this._mapData[itemIdx], "this._rollItems = ", this._rollItems.length);
            }, this.RAPID_FLY_TIME);
        }

        // console.log("====_featureGameViewsetRollData==1========= setRollData 停止单个 itemIdx==", itemIdx, "几个_isPlayRapidCount = ", this._isPlayRapidCount);
        for (let item of this._rollItems) {
            if (item.isRolling) {
                return;
            }
        }

        //全部停止
        // console.log("========_featureGameViewsetRollData===Main 全部停止=startRoll featureTimes==", 
        //     this.featureTimes , "this.featureData.maps.length = ", this.featureData.maps.length, "GameDataDefine.rapidhitCount ==", GameDataDefine.rapidhitCount,
        //     "featureCount = ", this.featureCount);
   
        if(this.featureTimes >= this.featureData.maps.length - 1){
            // console.log(itemIdx+"=====FeatureGamesetRollData===this.featureTimes====", this.featureTimes, "featureCount = ", this.featureCount,
            //     "featureFullEnd = ", this.featureFullEnd);
            this._playCoinSke();
        }else{

            /**有播放Rapid的动作则不在此处旋转下一轮牌面 */
            let TIME = 500
            // console.log(itemIdx+"=========_isPlayRapidCount========", this._isPlayRapidCount);
            if (this._isPlayRapidCount > 0 ) {
                TIME = 600 * this._isPlayRapidCount + 200;
                this._isPlayRapidCount = 0;
            }

            setTimeout(()=> {
                // console.log("====_featureGameViewsetRollData=====开始下一轮===nextRoll==TIME=====", TIME);
                this.featureTimes++;
                Eventer.getInstance().emit(GameEventType.nextRoll, true);
            }, TIME)
        }
        
        for (let i = this.boxAnimArr.length - 1; i >= 0; i--) {
            let tempA = this.boxAnimArr[i];
            tempA.removeFromParent();
        }
    }
}

export class RollItem {
    private _root: Node;
    private _images: IconData[];
    private _imgCount = 3;

    /**滚动速度 2000px/s向下 */
    private _speed = 3000;
    /**图标间距 */
    private _imgSpace = 128;
    /**停止时回弹修正速度 */
    private _stopSpeed = 500;
    /**随机id,百搭图标改变 */
    private _randomIdState: boolean = false;
    /**停止后 第一个图标的位置 */
    private _stopPosY = 0;
    /**开始旋转 */
    private _isRolling = false;
    /**开始修正位置 */
    private _isCorrect = false;

    /**最终显示的图标 */
    private _showIcons: IconData[];
    /**停后顺序 */
    private _stopIcons: IconData[];
    private _stopCall: Function;
    private _stopCaller: any;

    private _index: number;

    private stopRollData: StopRollData = new StopRollData();
    private OEN_SPEED_TIME = 1500; //每个Item滚动速度
    
    public get randomState() {
        return this._randomIdState;
    }
    
    public set randomState(state:boolean) {
        this._randomIdState = state;
    }

    public get isRolling() {
        return this._isRolling;
    }

    public node(): Node {
        return this._root;
    }

    // public setItemData(imgCount: number, stopPosY: number, speed: number, imgSpace): void {
    //     this._imgCount = imgCount;
    //     this._stopPosY = stopPosY;
    //     this._speed = speed;
    //     this._imgSpace = imgSpace;
    //     this.init();
    // }

    /**
     * 创建控制
     * @param root UI根节点
     * @param index 列索引
     */
    public constructor(root: Node, index: number) {
        this._root = root;
        this._index = index;
    }

    
    /**
     * 显示整列
     * @param isShow 是否显示 默认true
     */
    public getIndex() {
        return this._index;
    }



    /**
     * 显示整列
     * @param isShow 是否显示 默认true
     */
    public showListItem(isShow: boolean = true) {
        this._root.active = isShow;
    }

    public showFrameByIndex(index: number, ishow: boolean) {

        let img = this._stopIcons[index].node;
        if (img) {
            img.active = ishow;
        }
    }

    public setImgSprite(index: number, id: number): void {
        // console.log("id===", index, id);
        let img = this._stopIcons[index].node;
        // img.active = false;
        if (img) {
            let iconData = new IconData();
            iconData.node = img;
            iconData.id = id;
            img.getComponent(Item).setIcomData(iconData);
        }
    }

    public showFrameAll(): void {
        let len = this._images.length;
        for (let i = 0; i < len; i++) {
            this._images[i].node.active = true;
            this._images[i].node.setSiblingIndex(8);
        }
    }

    // 展示FeatureGameView 的 单个icon图标
    public init(iconId:number, val: number, col: number, row: number, ) {
        this._stopIcons = [];
        this._images = [];
        this._showIcons = [];
        LogUtil.debug("=======FeatureGameView==1==_recovery setItemCoinEffect init.iconId============", iconId, this._imgCount, val);
        for (let i = 0; i < this._imgCount; i++) {
            let imgConf = this._getIconConfig(iconId);
            let img = this._root.getChildByName(`Item_${i}`);
            let iconData = new IconData();
            iconData.id = imgConf.iconId;
            iconData.node = img;
            if (imgConf.iconId == 10){
                iconData.val = val;
            }
            img.getComponent(Item).setIcomData(iconData);
            img.getComponent(Item).setFeatureMask();
            
            this._images.push(iconData);
            if (i < this._imgCount - 1) {
                this._stopIcons.push(iconData);
            }
        }

        this._stopIcons.reverse();
    }
    /**随机id */
    private _getRandomIconConfig() {
        let keys = Config.getIconConfig().keys;
        let index = Math.floor(Math.random() * keys.length);
        if (index >= 10) {
            index = 1;
        }
        return Config.getRandomIconConfig(index);
    }

    // 如果id为0则随机一个 this._randomIdState 屏蔽
    private _getIconConfig(id: number) {
        if (id == 0) {
            id = GameUtils.randomInt(1, 9);
        }
        return Config.getIconConfigByKey(id);
    }

    public update(delta: number) {
        if (this._isRolling) {
            if (!this._isCorrect) {
                this._roll(delta);
            }
            else {
                this._correct(delta);
            }
        }
    }

    /**开始滚动 */
    public startRoll() {
        this._isRolling = true;
        this._isCorrect = false;
        this._showIcons = [];
        this._stopIcons = [];
        this._root.active = true;
        this.stopRollData = null;
        if (Global.quickSpin) {
            this._speed = 5000;
        } else {
            this._speed = this.OEN_SPEED_TIME;
        }
        for (let img of this._images) {
            img.node.active = true;
        }
    }

    private initTime = 0;
    /**
     * 停止滚动
     * @param stopRollData 图标id
     * @param call 回调函数
     * @param caller 回调对象
     */
    public stopRoll(isStopRollNow: boolean, stopRollData: StopRollData, call?: Function, caller?: any) {
        this.stopRollData = null;
        this.stopRollData = GameUtils.copyTab(stopRollData);
        this._stopCall = call;
        this._stopCaller = caller;
        this.initTime = new Date().getTime() / 1000;

        if (isStopRollNow) {
            this.stopRollNow();
        }
    }

    /**立即 */
    private stopRollNow() {
        // if (this.rollState == ROLLSTATE.ROLL_CUT) {

        if (!this.isRolling) {
            return;
        }
        // console.log("立即停this.rollState====", this._index, JSON.stringify(this.stopRollData.map));
        this._stopIcons = [];
        this._showIcons = [];
        // console.log(" 立即停且设置牌面this._images==", this._index, this._images);
        for (let i = 0; i < this._images.length; i++) {
            let item = this._images[i].node.getComponent(Item);
            if (i < this.stopRollData.map.length) {
                let len = this.stopRollData.map.length - 1;
                let id = this.stopRollData.map[len - i];
                let iconData = new IconData();
                iconData.id = id;
                item.setIcomData(iconData);
                this._images[i] = iconData;
            }
            let endPos = this._stopPosY + i * this._imgSpace;
            let pos = new Vec3(0, endPos - 40, 0);

            this._images[i].node.setPosition(pos);

            if (i == this._imgCount - 1) {
                this._stopIcons.reverse();
            } else {
                // this._showIcons.push(this._images[i]);
            }
            this._showIcons.push(this._images[i]);
            this._stopIcons.push(this._images[i]);

        }
        // this._images.reverse();
        // console.log(" 立即停且设置牌面this._images==", this._index, this._images);
        //  this._showIcons.push({ node: node, id: id, iconBet: bet });
        // this._showIcons.reverse();
        // this._stopIcons.push(...this._showIcons);
        this._isCorrect = true;
    }

    /**滚动
     * @param deltaTime 时间增量 ms
     */
    private _roll(deltaTime: number) {

        let distance = -this._speed * deltaTime / 1000;
        if (Math.abs(distance) >= this._imgSpace) {
            //console.log("超出单个图标间隔", distance);
            distance = -this._imgSpace / 2;
        }
        // if (this._index == 4) {
        //     console.log("distance", this._index, distance);
        // }
        let firstPos = this._images[0].node.getPosition();
        for (let i = 0; i < this._imgCount; i++) {
            let target = this._images[i].node.getPosition();
            let pos = new Vec3(target.x, target.y + distance, target.z);
            this._images[i].node.setPosition(pos);
        }
        //第一个图标移出屏幕
        if (firstPos.y < this._stopPosY - this._imgSpace) {
            let node = this._images.shift();
            let len = this._images.length - 1;
            let upNode = this._images[len];
            let upPos = upNode.node.getPosition();
            node.node.setPosition(new Vec3(upPos.x, upPos.y + this._imgSpace, upPos.z));  //置顶
            this._images.push(node);
            let imgConf: IconConfig;
            // let imgSource: string;
            let iconData = new IconData();
            if (this.stopRollData && this.stopRollData.map.length > 0) {
                //显示服务端图标
                let id = this.stopRollData.map.pop();
                imgConf = this._getIconConfig(id);
                console.log(" _featureGameViewsetRollData _roll 实际停止id==", id);
                iconData.node = node.node;
                iconData.id = id;
                iconData.name = imgConf.iconName;
                this._showIcons.push(iconData);
                // imgSource = imgConf.source_Normal;
            }
            else {  //随机显示图标
                imgConf = this._getRandomIconConfig();                
                iconData.id = imgConf.iconId; // 设置随机图标 ID
                if (iconData.id == 10) {
                    iconData.val = GameUtils.randomInt(1, 9);
                }
            }
            node.node.getComponent(Item).setIcomData(iconData, this._isRolling);
            node.node.getComponent(Item).setFeatureMask();
        }

        // if (this._showIcons && this._showIcons.length >= (this._imgCount - 1)) {
        if (this._showIcons && this._showIcons.length > 0) {
            let firstPos = this._showIcons[0].node.getPosition();
            if (firstPos.y <= this._stopPosY - 40) {  //第一个图标到达指定位置

                this._isCorrect = true;  //开始修正位置
                this._stopIcons.push(...this._showIcons);
                this._stopIcons.reverse();
                let pos = new Vec3(firstPos.x, firstPos.y, firstPos.z);

                for (let img of this._images) {  //隐藏不显示的图标
                    let exist = false;
                    let iconData = new IconData();
                    for (let icon of this._showIcons) {
                        let imgConf: IconConfig;
                        imgConf = this._getIconConfig(icon.id);
                        if (icon.node == img.node) {
                            iconData.id = icon.id;
                            pos.y += this._imgSpace;
                            icon.node.getPosition().y = pos.y;
                            exist = true;
                            break;
                        }
                    }
                    if (!exist) {
                        //img.active = false;
                        iconData.id = img.id;
                        pos.y += this._imgSpace;
                        img.node.getPosition().y = pos.y;
                        this._stopIcons.push(iconData);
                        this._showIcons.push(iconData);
                    }
                    img.node.getComponent(Item).setIcomData(iconData);
                    img.node.getComponent(Item).setFeatureMask();
                }
            }
        }
    }

    /**滚动结束，修正
     * @param deltaTime 时间增量 ms
     */
    private _correct(deltaTime: number) {
        let firstPos = this._showIcons[0].node.getPosition();
        let distance = this._stopSpeed * deltaTime / 1000;
        let targetDis = this._stopPosY - firstPos.y;  //距离停止点的距离
        if (distance > Math.abs(targetDis)) {
            distance = Math.abs(targetDis);
        }
        if (targetDis < 0) {  //还未到指定位置
            distance *= -1;
        }
        firstPos.y += distance;
        for (let i = 0; i < this._showIcons.length; i++) {
            this._showIcons[i].node.setPosition(firstPos.x, firstPos.y + i * this._imgSpace, firstPos.z);
        }

        if (firstPos.y == this._stopPosY) {
            this._isCorrect = false;
            this._isRolling = false;
            let time = new Date().getTime() / 1000;
            // console.log("isAllStopNum==", this._index, time - this.initTime);
            let pos = new Vec3(0, this._imgSpace, 0);
            let len = this._stopIcons.length - 1;
            this._stopIcons[len].node.setPosition(pos);
            this._images = [];
            for (let i = 0; i < this._stopIcons.length - 1; i++) {
                this._images.push(this._stopIcons[i]);
            }
            this._images.reverse();
            this._images.push(this._stopIcons[len]);

            if (this._stopCall && this._stopCaller) {
                this._stopCall.call(this._stopCaller, this._index);
            }
        }
    }
}