import { _decorator, Node, ScrollView, Sprite, Vec2 } from 'cc';
import { UIView } from '../../../../../scripts/framework/ui/UIView';
import GameResPath from '../../../../gamesCommon/script/constDatas/GameResPath';
import { Global } from '../../../../../scripts/main/Global';
import { ELanguage_Type } from '../../../../../scripts/common/define/EnumDefine';
import { Utils } from '../../utils/Utils';
import { Config } from '../../Config';
const { ccclass, property } = _decorator;

@ccclass('PayTableScrollView')
export class PayTableScrollView extends UIView {

    @property(Node)
    content: Node | null = null;

    @property(ScrollView)
    scrollViewEN: ScrollView | null = null;
    @property(ScrollView)
    scrollViewTC: ScrollView | null = null;
    @property(ScrollView)
    scrollViewSC: ScrollView | null = null;
    @property(ScrollView)
    scrollViewVI: ScrollView | null = null;
    @property(ScrollView)
    scrollViewMY: ScrollView | null = null;
    @property(ScrollView)
    scrollViewID: ScrollView | null = null;
    @property(ScrollView)
    scrollViewTH: ScrollView | null = null;
    @property(ScrollView)
    scrollViewPT: ScrollView | null = null;

    @property([Sprite])
    payTableImages: Sprite[] = [];

    @property(Sprite)
    leaveButton: Sprite | null = null;
    @property(Sprite)
    mask: Sprite | null = null;

    private scrollView:ScrollView = null;
    private lastScrollOffset: Vec2 = new Vec2();

    init(...args): void {
    }

    start() {
        // this.scheduleOnce(() => {
            this.showViewForLanguage()
            this.initializeScrollView();
            this.setupLeaveButton();
            this.setMaskButton();
            this.lastScrollOffset = this.scrollView?.getScrollOffset() || new Vec2();
        // }, 0.1);
    }   

    private initializeScrollView() {
        if (!this.scrollView || !this.content) {
            console.error('ScrollView or Content is not set!');
            return;
        }

        const language = navigator.language;
        console.error('ScrollView or navigator.language =', navigator.language, "Global.language = ", Global.language);

        // Global.language = navigator.language
        // 设置 ScrollView 的关键属性
        this.scrollView.horizontal = false;
        this.scrollView.vertical = true;
        this.scrollView.inertia = true;
        this.scrollView.brake = 0.75;
        this.scrollView.elastic = true;
        this.scrollView.bounceDuration = 0.23;

        // Global.language = navigator.language;
        // 添加滚动事件监听
        this.scrollView.node.on('scrolling', this.onScrolling, this);
    }

    /**展示多语言界面，没找到则展示英文界面 */
    private showViewForLanguage() {
        if (Global.language.includes(ELanguage_Type.EN)) {
            this.scrollViewEN.node.active = true;
            this.scrollViewTC.node.active = false;
            this.scrollViewSC.node.active = false;
            this.scrollViewVI.node.active = false;
            this.scrollViewMY.node.active = false;
            this.scrollViewID.node.active = false;
            this.scrollViewTH.node.active = false;
            this.scrollViewPT.node.active = false;       
            this.scrollView = this.scrollViewEN;
        }        
        else if (Global.language.includes(ELanguage_Type.TC)) {
            this.scrollViewEN.node.active = false;
            this.scrollViewTC.node.active = true;
            this.scrollViewSC.node.active = false;
            this.scrollViewVI.node.active = false;
            this.scrollViewMY.node.active = false;
            this.scrollViewID.node.active = false;
            this.scrollViewTH.node.active = false;
            this.scrollViewPT.node.active = false;  
            this.scrollView = this.scrollViewTC;
        }
        else if (Global.language.includes(ELanguage_Type.SC)) {
            this.scrollViewEN.node.active = false;
            this.scrollViewTC.node.active = false;
            this.scrollViewSC.node.active = true;
            this.scrollViewVI.node.active = false;
            this.scrollViewMY.node.active = false;
            this.scrollViewID.node.active = false;
            this.scrollViewTH.node.active = false;
            this.scrollViewPT.node.active = false;  
            this.scrollView = this.scrollViewSC;
        }
        else if (Global.language.includes(ELanguage_Type.VI)) {
            this.scrollViewEN.node.active = false;
            this.scrollViewTC.node.active = false;
            this.scrollViewSC.node.active = false;
            this.scrollViewVI.node.active = true;
            this.scrollViewMY.node.active = false;
            this.scrollViewID.node.active = false;
            this.scrollViewTH.node.active = false;
            this.scrollViewPT.node.active = false; 
            this.scrollView = this.scrollViewVI;
        }
        else if (Global.language.includes(ELanguage_Type.MY)) {
            this.scrollViewEN.node.active = false;
            this.scrollViewTC.node.active = false;
            this.scrollViewSC.node.active = false;
            this.scrollViewVI.node.active = false;
            this.scrollViewMY.node.active = true;
            this.scrollViewID.node.active = false;
            this.scrollViewTH.node.active = false;
            this.scrollViewPT.node.active = false; 
            this.scrollView = this.scrollViewMY;
        }
        else if (Global.language.includes(ELanguage_Type.ID)) {
            this.scrollViewEN.node.active = false;
            this.scrollViewTC.node.active = false;
            this.scrollViewSC.node.active = false;
            this.scrollViewVI.node.active = false;
            this.scrollViewMY.node.active = false;
            this.scrollViewID.node.active = true;
            this.scrollViewTH.node.active = false;
            this.scrollViewPT.node.active = false; 
            this.scrollView = this.scrollViewID;
        }
        else if (Global.language.includes(ELanguage_Type.TH)) {
            this.scrollViewEN.node.active = false;
            this.scrollViewTC.node.active = false;
            this.scrollViewSC.node.active = false;
            this.scrollViewVI.node.active = false;
            this.scrollViewMY.node.active = false;
            this.scrollViewID.node.active = false;
            this.scrollViewTH.node.active = true;
            this.scrollViewPT.node.active = false; 
            this.scrollView = this.scrollViewTH;
        }
        else if (Global.language.includes(ELanguage_Type.PT)) {
            this.scrollViewEN.node.active = false;
            this.scrollViewTC.node.active = false;
            this.scrollViewSC.node.active = false;
            this.scrollViewVI.node.active = false;
            this.scrollViewMY.node.active = false;
            this.scrollViewID.node.active = false;
            this.scrollViewTH.node.active = false;
            this.scrollViewPT.node.active = true; 
            this.scrollView = this.scrollViewPT;
        }
        else {
            this.scrollViewEN.node.active = true;
            this.scrollViewTC.node.active = false;
            this.scrollViewSC.node.active = false;
            this.scrollViewVI.node.active = false;
            this.scrollViewMY.node.active = false;
            this.scrollViewID.node.active = false;
            this.scrollViewTH.node.active = false;
            this.scrollViewPT.node.active = false;       
            this.scrollView = this.scrollViewEN;
        }  
    }

    private setupLeaveButton() {
        if (this.leaveButton) {
            this.leaveButton.node.on(Node.EventType.TOUCH_END, this.onLeaveButtonClicked, this);
        }
    }

    private onLeaveButtonClicked() {
        Utils.playClickSound(Config.clickSounds[3]);  
        // GameResPath.playRollCommonSound("click_1");
        this.close();
    }
    
    private setMaskButton() {
        if (this.mask) {
            this.mask.node.on(Node.EventType.TOUCH_END, this.onLeaveButtonClicked, this);
        }
    }

    onScrolling() {
        if (!this.scrollView) return;

        const currentOffset = this.scrollView.getScrollOffset();
        const deltaY = currentOffset.y - this.lastScrollOffset.y;

        // 可以在这里添加自定义的滚动逻辑
        console.log('Scrolling, deltaY:', deltaY);

        this.lastScrollOffset.set(currentOffset);
    }
}
