    // 获取心数量
    private _getScatterNum(map: number[]) {
        let scatterNum = 0;
        let list = null;
        let isPlay: boolean = false;
        let scatterIndexArray: number[] = [];;

        for (let i = 0; i < map?.length; i++) {
            if (GameDataDefine.isBelongsToScatter(map[i])) {
                scatterNum++;
                scatterIndexArray.push(i);
            }
            if (scatterNum == 2 && list == null) {
                list = Math.floor(i / 3);
            }
        }
        if (scatterNum >= 2) {
            isPlay = true;
        }
        let scatterData = {
            isPlay: isPlay,
            list: list,
            type: MapType.FREE,
            indexArray: scatterIndexArray,
        }
        return scatterData;
    }

    // 判断进入FeaTure时特效
    private _getCoinAndRapidNum(map: number[]) {
        let coinNum = 0;
        let list = null;
        let isPlay: boolean = false;

        for (let i = 0; i < map?.length; i++) {
            if (GameDataDefine.isBelongsToFeatureGame(map[i])) {
                coinNum++;
            }
            if (coinNum == 4 && list == null) {
                list = Math.floor(i / 3);
            }
        }
        if (coinNum >= 4) {
            isPlay = true;
        }
        let featureData = {
            isPlay: isPlay,
            list: list,
            type: MapType.FEATRUE,
        }
        return featureData;
    }

    /**列火焰框特效 */
    private _playScatterSke(index: number): void {
        this._scatterAct.active = true;
        if (this._rollItems[index]) {
            let localPos = this._rollItems[index].node().position;
            
            let vec3 = new Vec3(localPos.x, this._group_items.position.y, 0);
            this._scatterAct.setPosition(vec3);
            
            LogUtil.debug("==========_playScatterSke =index=========", index, "localPos = ", localPos);
            console.log(index+"_playScatterSke getPosition===", new Date().getTime(),this._scatterAct.getPosition().x);
        }
    }

    /**
     * 开始滚动
     */
    public startRoll() {
        this._isStopRollNow = false;        
        /**每列滚动的间隔 第一列转动多长时间后第二列开始转*/ 
        let inter = this.START_ROLL_TIME;
       
        let updown = this.UPDOWN;  /**符号整列提拉距离 */
        let upTime = this.UPTIME;  /**拉起时间 */
        let downTime = this.DOWNTIME; /**放下时间 */
        for (let i = 0; i < this._rollItems.length; i++) {
            let item = this._rollItems[i];
            tween(item.node())
            // .delay(inter*i)
            .by(upTime, {position: new Vec3(0, updown, 0)}, {easing: "sineOut"}) 
            .by(downTime, {position: new Vec3(0, -updown, 0)}, {easing: "sineIn"})
            .call(()=>{
                
                console.log("========_getRollIconDatadistance==100000====startRoll item==", i, TimeUtil.getCurMilliTime());
                item.startRoll();
            })
            .start();
        }
    }

    /**
     * 设置盘面 并停止
     * @param data 盘面数组
     * @param delay 延时设置
     */
    public setRollData(data: number[], lines: LineData[], coin: number[], delay?: number) {
        if (delay == undefined) {
            delay = this.ROLL_STOP_TIME;  // 第一列停止和第二列停止的间隔
        }
        this._curItemIdx = 0;
        this._lines = lines;
        this._mapData = [];
        this._mapData.push(...data);
        this._coinData = [];``
        this._coinData.push(...coin);

        let scatterData = this._getScatterNum(this._mapData);
        let featureData = this._getCoinAndRapidNum(this._mapData);

        this._stopKey.forEach((time) => {
            //Timer.clearTimeOut(time);
            clearTimeout(time);
        })

        this._stopKey = [];
        for (let i = 0; i < this._colCount; i++) {
            let extraDelay = this.ROLL_STOP_TIME;
            let base = 1;
            let delayed = 1;

            // 3、4列
            if (i > scatterData.list && scatterData.isPlay) {
                base = 1;
                // 最后一列心出现时，框要多展示一会儿
                // if ((i == 3) || (i == 4)) {
                delay = this.ROLL_SCATTER_STOP_TIME;

                console.log("========ROLL_STOP_SCATTER_TIME==ROLL_SCATTER_STOP_TIME i==", i, scatterData.list);
            }

            if (i > featureData.list && featureData.isPlay) {
                base = 1;
                extraDelay = this.ROLL_STOP_FEATURE_TIME;
                delayed = i - featureData.list;
            }

            if (this._isStopRollNow || Global.quickSpin) {
                base = this.STOP_NOW_BASE;
            }

            console.log("========ROLL_STOP_SCATTER_TIME==100000====startRoll item==", i, scatterData.list);
            // Base模式下 目前间隔150、300、450、600 停止 如果base为0.5则是75、150
            let delayTime = (delay * i + delayed * extraDelay) * base;
            LogUtil.debug("======ROLL_STOP_SCATTER_TIME===this.delayTime===", delayTime, "base = ", base, "delayed = ", delayed, "extraDelay = ", extraDelay, 
                "this._curItemIdx = ", this._curItemIdx, "this._isStopRollNow = ", this._isStopRollNow);
            
            if (scatterData.isPlay) {
                let scatterTime = 0
                if (i == 0) {
                    scatterTime = this.ROLL_SCATTER_STOP_0_TIME;
                }
                else if (i == 1) {
                    scatterTime = this.ROLL_SCATTER_STOP_1_TIME;
                }
                else if (i == 2) {
                    scatterTime = this.ROLL_SCATTER_STOP_2_TIME;
                }
                else if (i == 3) {
                    scatterTime = this.ROLL_SCATTER_STOP_3_TIME;
                }
                else if (i == 4) {
                    scatterTime = this.ROLL_SCATTER_STOP_4_TIME;
                }

                delayTime = (delay * i + scatterTime) * base;
            }

            let time = setTimeout(() => {
                let item = this._rollItems[this._curItemIdx];
                let start = this._curItemIdx * this._rowCount;
                let ids = this._mapData.slice(start, start + this._rowCount);
                let stopRollData = new StopRollData();
                stopRollData.map = ids;
                stopRollData.coin = [];
                stopRollData.curColIdx = this._curItemIdx;
                // TD 作用未知
                for (let i = 0; i < 3; i++) {
                    if (stopRollData.map[i] == 10) {
                        let k = this._curItemIdx * 3 + i
                        stopRollData.coin[this.count] = this._coinData[k];
                        this.count++;
                    }
                }

                LogUtil.debug("====_isCorrect==1==setRollData========this._mapData===", this._mapData);
                LogUtil.debug("====_isCorrectisRolling==1==setRollData========this._curItemIdx===", this._curItemIdx, "item.isRolling = ", item.isRolling);
                if (item.isRolling) {
                    item.stopRollItem(this.isStopRollNow, stopRollData, this._onOneStop, this);
                }
                this._curItemIdx++;
            }, delayTime);
            this._stopKey.push(time);
        }
    }

