import { _decorator, Component, Node, SpriteFrame, Sprite, Label, sp, Vec4 } from 'cc';
import { ResManager } from '../../../../../scripts/framework/manager/ResManager';
import { Global } from '../../../../../scripts/main/Global';
import { IconData } from '../../GameDataDefine';
import { Config, RES, Resource } from '../../Config';
import { GameUtils } from '../../../../../scripts/common/utils/GameUtil';
import LogUtil from '../../../../../scripts/common/utils/LogUtil';
import { Utils } from '../../utils/Utils';
const { ccclass, property } = _decorator;

@ccclass('Item')
export class Item extends Component {
    @property(Node)
    private img_icon: Node;
    @property(Label)
    private coinVal: Label;
    @property(sp.Skeleton)
    private stopAnim: sp.Skeleton;
    @property(Node)
    private img_mask: Node;

    private animPath:string;

    public iconData: IconData;
    
    public setIcomData(iconData: IconData, isRolling: boolean = false): void {
        this.iconData = iconData;
        if (this.iconData.node == null) {
            this.iconData.node = this.node;
        }
        let imgConf = Config.getIconConfigByKey(this.iconData.id);
        // LogUtil.debug("====inFreeGame==_setRollIconDataimgConf=this.iconData.id====", this.iconData.id, "imgConf = ", imgConf);
        this.iconData.name = imgConf.iconName;
        this.animPath = imgConf.path;
        let path = isRolling ? imgConf.source_Roller : imgConf.source_Normal;
        ResManager.Instance().load(Global.gameId + "", path, SpriteFrame, () => { }, (evt: any) => { this.img_icon.getComponent(Sprite).spriteFrame = evt.data; });
    
        if(imgConf.iconId == 10) {
            // LogUtil.debug("====inFreeGame===this.iconData222.val============", iconData.val);
            let val = iconData.val
            if (val == 0 || val == null) {
                // val = GameUtils.roundFloat(GameUtils.randomFloat(1, 9), 2);
                val = GameUtils.randomInt(1, 8);
                this.setItemCoinVal(true, `${val}.00`);
            }
            else {
                if (Number.isInteger(val)) {
                    this.setItemCoinVal(true, `${val}.00`);
                }
                else {
                    this.setItemCoinVal(true, val.toString());
                }
            }
            
            // LogUtil.debug("id===",  "indexO iconData.val = ", iconData.val);
        }
        else {
            this.setItemCoinVal(false, "0");
        }
        
        this.setItemRolling(isRolling);
    }


    //设置特殊硬币上得值
    private setItemCoinVal(isShow:boolean, val:string){
        if(this.coinVal){
            this.coinVal.node.active = isShow;
            this.coinVal.string = `${val}`;
        }
    }

    // 设置虚化
    private setItemRolling(isRolling:boolean){
        // console.log("=========setItemRolling======",isRolling);
        // let _spr = this.img_icon.getComponent(Sprite);
        // let aa = _spr?.getMaterialInstance(0);
        // aa?.resetUniforms(true);
        // if(isRolling){
        //     if(_spr?.customMaterial){
        //         aa?.setProperty('range',4);
        //         // aa?.setProperty('color', new Vec4(1, 0, 0, 1));
        //         aa?.setProperty('shadowAmount',4);
        //     }
        // }else{
        //     if(_spr?.customMaterial){
        //         aa?.setProperty('range',0);
        //         aa?.setProperty('shadowAmount',1);
        //     }
        // }
    }

    public stopView(isPlayScatterAnim){
        // 心+RepidHit落下时播放down动画
        console.log("=========stopItemView= this.iconData.id=====", this.iconData.id, "isPlayScatterAnim = ", isPlayScatterAnim);
        if(this.iconData.id == 9 || this.iconData.id == 10 || (this.iconData.id == 11 && isPlayScatterAnim)){
            let ske = new Resource(this.animPath, sp.SkeletonData);
            let data = RES.getRes(ske, sp.SkeletonData);
            this.stopAnim.node.active = true;
            this.stopAnim.clearTrack(0);
            this.stopAnim.setToSetupPose();
            this.stopAnim.skeletonData = data;
            let anim = "down";
            // 默认是down 金币是scale 出现时的声音不同
            if (this.iconData.id == 9) {
                Utils.playSound(Config.sounds[19]);
            }
            else if (this.iconData.id == 10) {
                anim = "scale";
                Utils.playSound(Config.sounds[18]);
            }
            this.stopAnim.setAnimation(0, anim, false);
            this.stopAnim.setCompleteListener((x:sp.spine.TrackEntry)=>{
                console.log("=========stopItemView======",x.animation.name);
                this.stopAnim.node.active = false;
            });

            let valNode = this.stopAnim.node.getChildByName("Node");
            valNode.active = false;
        }
    }

    // 设置Feature模式下mask
    public setFeatureMask(){
        if(this.iconData.id == 9 || this.iconData.id == 10){
            this.img_mask.active = false;
        }else{
            this.img_mask.active = true;
        }
    }
    
    // 获取当前icon是否是scatter
    public getIconDataIsScatter(){
        let state = false;
        if(this.iconData.id == 11){
            state = true;            
        }  
        return state;    
    }

    // 设置Free模式下mask
    public setFreeMask(state){
        if (state) {
            if(this.iconData.id == 11){
                this.img_mask.active = false;
                
            }else{
                this.img_mask.active = true;
            }
        }
        else {
            this.img_mask.active = false;
        }        
    }

    public setIcon(){
        if(this.iconData.id == 9 || this.iconData.id == 10){
            this.img_icon.active = false;
        }else{
            this.img_icon.active = true;
        }
    }
    


}

