import { _decorator, Animation, animation, Component, instantiate, Node, Prefab, Vec3 } from 'cc';
import { RollItem } from './RollIconCom';
import { Timer } from '../../utils/Timer';
import { ResManager } from '../../../../../scripts/framework/manager/ResManager';
import { Global } from '../../../../../scripts/main/Global';
import { StopRollData } from '../../GameDataDefine';
const { ccclass, property } = _decorator;

@ccclass('LightningCom')
export class LightningCom extends Component {

    private _listArr: Node[]
    /**滚动速度 2000px/s向下 */
    private _speed = 800;
    /**图标间距 */
    private _imgSpace = 71;
    /**停止后 第一个图标的位置 */
    private _stopPosY = 0;
    /**盘面数据 */
    private _mapData: number[];
    private _stopKey: number[] = [];
    private _imgCount = 2;
    private _curItemIdx = 0;
    private _rowCount = 1;  //行数
    private _colCount = 4;  //列数
    private _rollItems: RollItem[];
    private _lightningNode: Node;
    private _allStop: boolean = true;
    private _idArr = [1, 2, 3, 4];
    public init(): void {
        this._listArr = [];
        this._rollItems = [];
        for (let i = 0; i < this._colCount; i++) {
            let listNode = this.node.getChildByName(`list_${i}`);
            this._listArr.push(listNode);
            let node = this.node.getChildByName(`list_${i}`);
            let item = new RollItem(node, i);
            item.setItemData(this._imgCount, this._stopPosY, this._speed, this._imgSpace);
            item.setImgSprite(0, this._idArr[i]);
            this._rollItems.push(item);
        }

    }

    public initIcon(): void {
        for (let i = 0; i < this._idArr.length; i++) {
            let item = this._rollItems[i];
            if (item) {
                item.setImgSprite(0, this._idArr[i]);
            }
        }
    }

    public setLightningImgSprite(idArr: number[]): void {
        for (let i = 0; i < idArr.length; i++) {
            let list = this._idArr.indexOf(idArr[i]);
            let index = 0;
            let item = this._rollItems[list];
            if (item) {
                item.setImgSprite(index, 11);
            }
        }
    }
    public playAni(): void {
        // let path = "resources/atlas/main/efffect/FREE_SPINS_Electricity_15FPS_Trim/FREE_SPINS_Electricity";
        // ResManager.Instance().load(Global.gameId + "", path, Prefab, () => { }, (evt: any) => {
        //     let pre = instantiate(evt.data);
        //     this._lightningNode = pre;
        //     this.node.addChild(pre);
        // });
    }

    public removeAni(): void {
        if (this._lightningNode && this._lightningNode.parent) {
            this._lightningNode.parent.removeChild(this._lightningNode);
            this._lightningNode = null;
        }
    }

    public update(delta: number): void {
        // for (let item of this._rollItems) {
        //     item.update(delta);
        // }
    }

    public hideItem(): void {
        for (let item of this._rollItems) {
            item.node().active = false;
        }
    }


    /**
      * 开始滚动
      */
    public startRoll(data: number[]) {
        this._allStop = false;
        for (let i = 0; i < data.length; i++) {
            this._rollItems[i].startRoll();
        }
    }

    /**
        * 设置盘面 并停止
        * @param data 盘面数组
        * @param delay 延时设置
        */
    public setRollData(data: number[], delay?: number) {
        if (delay == undefined) {
            delay = 300;
        }
        this._curItemIdx = 0;
        this._mapData = [];
        this._mapData.push(...data);

        this._stopKey.forEach(time => {
            Timer.clearTimeOut(time);
        })
        this._stopKey = [];
        for (let i = 0; i < this._colCount; i++) {
            let extraDelay = 1000;
            let base = 1;
            let delayed = 1;

            let time = Timer.setTimeOut(this, () => {
                let item = this._rollItems[this._curItemIdx];
                let start = this._curItemIdx * this._rowCount;
                let ids = this._mapData.slice(start, start + this._rowCount);
                let stopRollData = new StopRollData();
                stopRollData.map = ids;
                item.stopRollItem(false, stopRollData, this._onOneStop, this);
                this._curItemIdx++;
            }, (delay * i + delayed * extraDelay) * base);
            this._stopKey.push(time);
        }
    }

    public getRollState(): boolean {
        return this._allStop;
    }
    /**
      * 某一列停止
      * @param index 列索引
      * @returns 
      */
    private _onOneStop(index: number) {
        for (let item of this._rollItems) {
            if (item.isRolling) {
                return;
            }
        }
        this._allStop = true;
        //("LightningComAllStop");
    }

}

