import { Vec3, _decorator, Node, UITransform, AssetManager, assetManager } from 'cc';
import { BetMap, FeatureMap } from './net/Protocol';
import { GameUtils } from '../../../scripts/common/utils/GameUtil';
import LogUtil from '../../../scripts/common/utils/LogUtil';
import { ServerProxy } from './net/ServerProxy';
import GamesData from '../../gamesCommon/script/GamesData';

/** 游戏数据 */
class GameDataManager {

    /** Base 模式下数据 */
    public _baseMap = [];
    /** Featrue 模式下数据 */
    public _featrueMap ;

    /** Base 模式下数据 */
    public _freeTimes = [];

    /** Base 模式下数据 */
    public _coinval = [];

    public getBaseMap(){
        return this._baseMap;
    }

    public setBaseMap(baseMap:BetMap[]){
        for (var baseData of baseMap) {
            this._baseMap.push(baseData);
        }
        
        this.setCoinValMap(this._baseMap[0].map)
        LogUtil.debug("=======setBaseMap==2=this._coinval============", this._coinval);

        // this._freeTimes = [];
        // this._freeTimes.push(message.free.length);
        // for (var free of message.free) {
        //     this._baseMap.push(free);
        // }
    }

    
    // 获取随机金币展示值map
    public getCoinValMap(){
        return this._coinval;
    }

    // 设置随机金币展示值map
    public setCoinValMap(map: number[]){
        if (map) {
            for (var data of map) {
                if (data == 10){
                    let val = GameUtils.randomInt(1, 8);
                    this._coinval.push(val);
                }
            }
        }
        else{
            this._coinval = []
        }
    }

    // 进入Feature界面 + 播放动效时 id = 0 每次点击时 id 传入this.featureTimes。具体哪个值是id
    public getFeatureCoinMap(id, index:number){
        this._featrueMap = ServerProxy.getInstance().getFeatureItemArray()
        let linesTemp = null;
        let rate = 0
        
        if (this._featrueMap && this._featrueMap.maps[id]) {
            console.log("=====FeatureGameView==1=getFeatureCoinMap======_featrueMap.maps===", this._featrueMap.maps);
            linesTemp = this._featrueMap.maps[id].lines;
        }
        else if (this._featrueMap && this._featrueMap.base[id]) {
            console.log("=====FeatureGameView==1=getFeatureCoinMap======_featrueMap.maps===", this._featrueMap.maps);
            linesTemp = this._featrueMap.base[id].lines;
        }

        if (linesTemp) {
            for (let i = 0; i < linesTemp.length; i++) {
                if (index == linesTemp[i].add) {
                    rate = linesTemp[i].rate
                    break;
                }
            }
        }

        let val = GamesData.formatScore(rate, false);

        //  1.4000000000000001
        console.log("=====FeatureGameView==1==getFeatureCoinMap========rate===", rate, "val = ", val, "id = ", id, "index = ", index, "Number(val) = ", Number(val), "===linesTemp===", linesTemp);
        return Number(val); //rate/1000000
    }

    public getFeatureMap(){
        this._featrueMap = ServerProxy.getInstance().getFeatureItemArray()
        return this._featrueMap;
    }


    public setFeatureMap(map:FeatureMap[]){
        if (!this._baseMap || this._baseMap.length == 0) {
            return null;
        }
        let bmap = this._baseMap.shift();
        
        let featureInitMap = bmap.map.slice(0, map.map.length);

        
        // this._featrueMap = {
        //     "init_map": featureInitMap,
        //     "maps": map,
        // }
    }
}

export default new GameDataManager();