    protected update(deltaTime: number) {
        let delta = Math.floor(deltaTime * 1000);
        if (delta > 200) {  //200ms以上的认为卡顿，则丢弃
            return;
        }
        Timer.update(delta);
        this._updateCom(delta);
    }

