    // MainView UI 入场动画
    private MainViewUiAnim() {
        let Jackpot_Frame = this._center.getChildByName("Jackpot_Frame");
        let ReelArea = this._center.getChildByName("ReelArea");
        let rollIconCom = this._center.getChildByName("rollIconCom");
        let group_wineffect = this._center.getChildByName("group_wineffect");
        let group_lines = this._center.getChildByName("group_lines");   
        let FeatureGameView = this._center.getChildByName("FeatureGameView");   
           
        let startPosJackpot = new Vec3(620, 325, 0);
        let endPosJackpot = new Vec3(120, 325, 0);     
        let startPosReel = new Vec3(500, 9, 0);
        let endPosReel = new Vec3(0, 9, 0);   
        let startPos = new Vec3(500, 0, 0);
        let endPos = new Vec3(0, 0, 0);
    
        Jackpot_Frame.setPosition(startPosJackpot);
        ReelArea.setPosition(startPosReel);
        rollIconCom.setPosition(startPos);
        group_wineffect.setPosition(startPos);
        group_lines.setPosition(startPos);
        FeatureGameView.setPosition(startPos);

        let TIME = 0.5
        tween(Jackpot_Frame)
        .to(TIME, {position: endPosJackpot}, {easing: "sineOut"})
        .start();
        
        tween(ReelArea)
        .to(TIME, {position: endPosReel}, {easing: "sineOut"})
        .start();
        
        tween(rollIconCom)
        .to(TIME, {position: endPos}, {easing: "sineOut"})
        .start();
        
        tween(group_wineffect)
        .to(TIME, {position: endPos}, {easing: "sineOut"})
        .start();
        
        tween(group_lines)
        .to(TIME, {position: endPos}, {easing: "sineOut"})
        .start();   
        
        tween(FeatureGameView)
        .to(TIME, {position: endPos}, {easing: "sineOut"})
        .start();   
    }

    // Bottom UI 入场动画
    public bottomAnim(state?) {
        let ControlPanel = this._center.getChildByName("ControlPanel");
        let bottom_bg = ControlPanel.getChildByName("bottom_bg");
        let startPos = new Vec3(0, -1200, 0);
        let endPos = new Vec3(0, -529.5, 0);
        if (state == "out") {
            bottom_bg.active = true;
            startPos = new Vec3(0, -529.5, 0);
            endPos = new Vec3(0, -1200, 0);
        }
        else {
            bottom_bg.active = false;
            setTimeout(() => {
                let bottom_bg = ControlPanel.getChildByName("bottom_bg");
                bottom_bg.active = true;
            }, 100);
        }

        bottom_bg.setPosition(startPos);

        // Bottom动画开始时禁止点击，完成后可以点击
        this.bottom.setStartBtnState(0, false);
        let onFinish = () => {
            if (this._recoveryData) {
                this.recoveryManager(this._recoveryData);
                this._recoveryData = null;
            }

            this.bottom.setStartBtnState(0, true);
            console.log("====_showEnterAnim =="); 
        };

        let TIME = 1
        tween(bottom_bg)
        .to(TIME, {position: endPos}, {easing: "sineOut"})
        .call(onFinish)
        .start();        
    }

