    private _clickBG(evt: EventTouch) {
        Log.d(Config.logTag, "on Click Bg");
        Log.d(Config.logTag, "on Click new Bg",evt.getUILocation());
        // Log.d(Config.logTag, "on Click new Bg",evt.touch.getLocation());
        Eventer.getInstance().emit(GameEventType.RollBackgroundClick, this);
        
        let _clickEff = instantiate(this._clickFire);
        _clickEff.active = true;
        let localN = this._clickFire.parent.getComponent(UITransform);
        let pos = localN.convertToNodeSpaceAR(new Vec3(evt.getUILocation().x, evt.getUILocation().y, 0));
        _clickEff.setPosition(pos);
        _clickEff.parent = this._clickFire.parent;
        let fireSke = _clickEff.getComponent(sp.Skeleton)
        fireSke.clearTrack(0);
        fireSke.setToSetupPose();
        fireSke.setAnimation(0, "animation", false);
        fireSke.setCompleteListener(()=>{
            _clickEff.removeFromParent();
        });
    }

