    /**登录初始化后 自动回放 */
    private playPlayback() {
        UIManager.getInstance().closeToUI(UIID_GAME.BigWinView);
        let vo = ServerProxy.getInstance().java2cPlayback();

        GameCommonModel.getInstance().betList = [vo.gameRes.bet];
        GameCommonModel.getInstance().coinRate = vo.gameRes.coin_rate;
        this.initPrefix();
        let lines = [vo.gameRes.line_num];
        this.bottom.setLineArray(lines);
        this.bottom.setLineIndex(lines.length - 1);
        this.bottom.setWinMoney(0);
        this.bottom.setMoney(vo.startScore * GamesData.exchange);
        // this.bottom.hideScoreNode();
        this.gameComModel.curBetIndex = 0;
        this.bottom.setBetIndex(this.gameComModel.curBetIndex);
        //("自动回放vo==", GameCommonModel.getInstance().betList, this.gameComModel.curBetIndex);
        setTimeout(() => {
            this._startRoll();
        }, 1500)

    }
