    // 展示jackpot 下砸win盘面特效
    private _showJackpotFrameAnim(val) {
        let TIME1 = 2; // 金币放大的时间
        let TIME2 = 1; // 金币跳动到最大值的时间ms
        let TIME3 = TIME1 + TIME2; // 金币缩小的时间
        let topX = -120;
        let topY = -200;
        let posY = -750;
        // this.jackpotItemId
        let curJackpotItem = this.jackpotItems[val];
        let node = curJackpotItem.node;
        
        let finishi = ()=> {
            node.active = false;
        }
        let act1 = tween(node)
            .to(TIME1, { 
                scale: new Vec3(1.2, 1.2, 1.2), 
                position: new Vec3(topX, topY, 0) 
            }, {easing: "expoOut"});  // 放大1.2倍
        let act2 = tween(node)
            .call(finishi)
            .to(TIME2, { 
                scale: new Vec3(1, 1, 1), 
                position: new Vec3(topX, posY, 0) 
            }, {easing: "expoIn"});  // 金币缩小0.6倍
        tween(node).sequence(act1, act2).start();
        
        this._winCoinEffect = node.getChildByName("win_coin_effect");
        let lightNode = node.getChildByName("win_coin_light_effect");
        tween(lightNode).delay(TIME3).call(()=>{
                let ske = lightNode.getComponent(sp.Skeleton);   
                let path = "resources/anim/feature/1001_collect";
                let skeRes = new Resource(path, sp.SkeletonData);
                let data = RES.getRes(skeRes, sp.SkeletonData);
                lightNode.active = true;
                ske.clearTrack(0);
                ske.setToSetupPose();
                ske.skeletonData = data;
                ske.setAnimation(0, "light", false);
            }).start();
    }

