    /**请求 */
    private _sendBet() {
        if (Global.playback) {
            return true;
        }
        let bet = this.gameComModel.curBet;
        let line = this.rollComModel.curBetLine;
        let money = this.gameComModel.money;

        console.log("====_sendBet====this.gameComModel===", this.gameComModel, "money = ", this.gameComModel.money, "bet = ", bet, "this.totalBet = ", this.totalBet);

        if (bet * line <= 0) {
            //  LogUtil.debug(Config.logTag, `bet has error: bet(${bet}) line(${line})`);
            return false;
        }

        money = money - this.totalBet;

        ServerProxy.getInstance().c2sSlotBet({ bet: bet });
        
        this.bottom.setMoney(money);
        return true;

    }

