    /**
     * 计算所有中奖图标的特效需要数据，小恶魔合成
     */
    private calcAllWinItem(): void {       
        this._itemArrId = [];
        this._itemArrIndex = [];
        this._itemArrIndexMap = [];
        this._lineArr = [];
        this._winIdArr = [];
        this._tempD = {};
        let len: number = this._winData.winLines.length;
        let len1: number;
        let winLineVo: WinLineVo;
        let index: number;
        let showIndexAll: number[][] = [];
        for (let i: number = 0; i < len; i++) {
            winLineVo = this._winData.winLines[i];
            len1 = winLineVo.itemImgId.length;
            showIndexAll.push(winLineVo.itemIndex);
            for (let j: number = 0; j < len1; j++) {
                index = winLineVo.itemIndex[j];
                if (this._itemArrIndex.indexOf(index) == -1) {
                    this._itemArrIndex.push(index);
                    this._itemArrIndexMap[index] = true;
                    this._itemArrId.push(winLineVo.itemImgId[j]);
                }
            }
            this._lineArr.push(winLineVo.line);
            this._winIdArr.push(winLineVo.winImgId)
        }

        // Feature 回 base 报错
        this._tempD = this.getXiaoEmoNum(this._itemArrId, this._itemArrIndex);
        LogUtil.debug("=========1 calcAllWinItem==this._itemArrId===addTempD======", this._itemArrId, "this._itemArrIndex = ", this._itemArrIndex);
    }
    
    /**
     * 获取当前数字在第几列
     */
    private addTempD(aa, map, i){
        if (!this._itemArrIndexMap[i] && map[i] == 8) {
            aa.push(i)
        }
    }
    /**
     * 获取当前数字在第几列
     */
    private exTempD(aa, map, index){
        // 第几列
        let row = index % 3;
        let i = 0;
        let j = 0;
        if (row == 0) {
            i = index + 1;
            j = index + 2
        }
        else if (row == 1) {
            i = index - 1;
            j = index + 1
        }
        else if (row == 2) {
            i = index - 1;
            j = index - 2;
        }

        this.addTempD(aa, map, i);
        this.addTempD(aa, map, j);
    }

    /**
     * 获取小恶魔在每列的数量
     */
    private getXiaoEmoNum(itemId, itemIndex){
        if (!this._mapData) {
            Log.e("getXiaoEmoNum itemId = ", itemId)
            return
        }
        
        let aa = [];
        let map = this._mapData.map;
        for (let i = 0; i < itemIndex.length; i++) {
            const index = itemIndex[i];
            let id = itemId[i];
            if(id == 8){
                this.exTempD(aa, map, index);
                aa.push(index);
            }
        }
        aa.sort((a, b)=>{
            return a - b;
        });
        // LogUtil.debug("=====getXiaoEmoNum==小恶魔==1===addTempD==========", aa);
        let bb = {};
        for (let i = 0; i < aa.length - 1; i++) {
            const local1 = aa[i];
            const local2 = aa[i+1];
            if(Math.floor(local1/3) === Math.floor(local2/3)){
                if(bb[Math.floor(local1/3)]){
                    bb[Math.floor(local1/3)].count++;
                    bb[Math.floor(local1/3)].idx = local2;
                }else{
                    if((aa[i+1] - aa[i]) != 2) {
                        let tempc = aa[i+1] - aa[i] + 1;
                        bb[Math.floor(local1/3)] = {listp:Math.floor(local1/3), count:tempc, idx:local2};
                    }
                }
            }
        }
        // LogUtil.debug("====getXiaoEmoNum===小恶魔==2=============", bb);
        return bb;
    }

