    /**
     * 显示总赢奖提示 bottom 单次赢奖值 
     * 
     */
    private _showTotalWinTips(isPlayCoin, reward?:number, isNotShowCoin?:boolean) {
        // let totalWin = this._winData.add;
        this._totalWin += reward;
        LogUtil.debug("_showTotalWinTips getBigWinTypeEmo getReward _totalWin ==", this._totalWin, "isPlayCoin = ", isPlayCoin, "geReward reward = ", reward
            , "isNotShowCoin = ", isNotShowCoin,
        );

        if (isPlayCoin) {
            if (reward > 0) {
                let winStr = Config.getText("mainGame002");
                let score = Utils.formatScore(reward);
                winStr = GamesData.replaceString(winStr, [score]);
                this._showWinNumberAnim(reward);
            }
    
            // let Label_tips: Node = Label_name.parent.getChildByName("Label_tips")
            let data = {
                type: ROLL_BOTTOM_WIN_LINE_TYPE.TOTAL,
                totalWin: this._winData.add,
            }
            Eventer.getInstance().emit(GameEventType.RollShowWinningLine, data);
            this.bottom.addToWinMoney(this._totalWin);
        }
        else {
            if (!isNotShowCoin) {
                this._showCoinWin(reward);
            }
            this.bottom.setWinMoney(this._totalWin);
        }
    }

