        Utils.stopMusic(2);

        //播放打铃音效2s（目前资源是4秒） 时长和主角小恶魔播放特效attack是一样的 3个Scatter颤抖的声音
        Utils.playSound(Config.sounds[20]);
        // 隐藏Item
