import { featureCoinData, FeatureLineData, featureRapidData, LineData } from "../GameDataDefine";

/**
 * 消息协议
 */
export class Protocol {
    /**玩家信息 */
    public static USERINFO = "userinfo";
    /**請求押注信息 */
    public static SLOTINFO = "slot_info";
    /**押注消息 */
    public static SLOTBET = "slot";
    /** 中断返回数据*/
    public static LASTMAP = "last_map";
    /**每次免费发送 */
    public static FREESPIN = "free_spin";
    /**购买免费 */
    public static SLOT_BUY = "buy_free";
}

export interface SlotBetVo_c2s {
    bet: number;
}

export interface FreeSpinVo_c2s {
    times: number;
    type: number;
}

export interface BetMap {
    /** 牌面 */
    map: number[];
    /**初始图标列表 */
    init_map: number[];
    /** 中线 */
    lines: LineData[];
    /** 牌面加分 */
    score: number;
    /** 倍数 */
    multiple:number;
    /** 金币值 */
    coin: number[];
}

export interface FreeMap {
    /** 牌面 */
    map: number[];
    /** 中线 */
    lines: FeatureLineData[];
    /** 牌面加分 */
    score: number;
    /** 倍数 */
    multiple:number;
}

export interface FeatureMap {
    /** 图标列表 */
    map: number[];
    /** 中线 */
    lines: FeatureLineData[];
    /** 倍数 jackpot */
    multiple:number;
}

// s2c_slot
export interface SlotBetVo_s2c {
    base: BetMap[];
    free: BetMap[];
    feature: FeatureMap[];
    reward: number;
}

// 後端上線主動推送 s2c_last_map
export interface LastMap {
    /**上局牌面 */
    base: BetMap[];
    free: BetMap[];
    feature: FeatureMap[];
    win: number;
    bet: number;
}