import { _decorator, Component, EventTouch, Node, NodeEventType } from 'cc';
import AudioManager from '../../../../../scripts/framework/manager/AudioManager';
import GamesData from '../../../../gamesCommon/script/GamesData';
import { Eventer } from '../../../../../scripts/framework/Eventer';
import { Config } from '../../Config';
import { ScreenType, UIView } from '../../../../../scripts/framework/ui/UIView';
import { Global } from '../../../../../scripts/main/Global';
import { GameEventType } from '../../../../gamesCommon/script/GameEventType';
const { ccclass, property } = _decorator;

@ccclass('setCom')
export class setCom extends UIView {

    @property(Node)
    private mask: Node;
    @property(Node)
    private quickBtn: Node;
    @property(Node)
    private musickBtn: Node;
    @property(Node)
    private soundBtn: Node;

    start() {
        //this.init();
    }

    private onEven(): void {
        this.quickBtn.on(NodeEventType.TOUCH_END, this._onClickEvent, this);
        this.musickBtn.on(NodeEventType.TOUCH_END, this._onClickEvent, this);
        this.soundBtn.on(NodeEventType.TOUCH_END, this._onClickEvent, this);
        this.mask.on(NodeEventType.TOUCH_END, this.hide, this);
    }

    private offEvent(): void {
        // this.quickBtn.off(NodeEventType.TOUCH_END, this._onClickEvent, this);
        // this.musickBtn.off(NodeEventType.TOUCH_END, this._onClickEvent, this);
        // this.soundBtn.off(NodeEventType.TOUCH_END, this._onClickEvent, this);
        // this.mask.off(NodeEventType.TOUCH_END, this.hide, this);
        Eventer.getInstance().off(GameEventType.ScreenSwitch);
    }

    private _onClickEvent(evt: EventTouch): void {
        switch (evt.target) {
            case this.quickBtn:
                this.onQuick();
                break;
            case this.musickBtn:
                this.onMusick();
                break;
            case this.soundBtn:
                this.onSound();
                break;
        }

    }
    public init(): void {
        this.node.active = false;
        AudioManager.Instance().musicEnabled = true;
        AudioManager.Instance().setSoundEnabled(true);
        this.onEven();
        this.onScreenSwitch();
        Eventer.getInstance().emit(Config.changeQuick, false);
        this.quickBtn.getChildByName('img_check').active = false;
        this.musickBtn.getChildByName('img_check').active = AudioManager.Instance().musicEnabled;;
        this.soundBtn.getChildByName('img_check').active = AudioManager.Instance().soundEnabled;
        Eventer.getInstance().on(GameEventType.ScreenSwitch, this.onScreenSwitch, this);
    }

    private onScreenSwitch(): void {
        if (Global.gameScreenType == ScreenType.Landscape) {
            this.node.angle = 0;
        } else {
            // this.node.angle = 90;
        }
    }

    private onQuick(): void {
        let img_check = this.quickBtn.getChildByName('img_check');
        img_check.active = !img_check.active;
    }

    private hide(): void {
        this.node.active = false;
        let img_check = this.quickBtn.getChildByName('img_check');
        Eventer.getInstance().emit(Config.changeQuick, img_check.active);
    }

    private onMusick(): void {
        let playSound: boolean = !AudioManager.Instance().musicEnabled;
        let img_check = this.musickBtn.getChildByName('img_check');
        img_check.active = playSound;
        if (playSound) {
            this.playMusic();
        } else {
            this.stopMusic();
        }
    }

    /** 
      * stopMusic 用于开关背景音乐和音效的
     */
    private stopMusic() {
        AudioManager.Instance().musicOff();
        AudioManager.Instance().musicEnabled = false;
        AudioManager.Instance().audioSource.volume = 1;
        AudioManager.Instance().audioSource.stop();
    }
    /**
      * playMusic 用于开关背景音乐和音效的
      */
    private playMusic() {
        AudioManager.Instance().musicEnabled = true;
        AudioManager.Instance().musicOn();
        if (!GamesData.musicInfo) { return; }
        AudioManager.Instance().playMusic(GamesData.musicInfo.url, GamesData.musicInfo.bundleName);
    }


    private onSound(): void {
        let playSound: boolean = !AudioManager.Instance().soundEnabled;
        let img_check = this.soundBtn.getChildByName('img_check');
        img_check.active = playSound;
        if (playSound) {
            this.playSound();
        } else {
            this.stopSound();
        }
    }

    private stopSound(): void {
        AudioManager.Instance().setSoundEnabled(false);
        Eventer.getInstance().emit(Config.changeSound, false);
        //AudioManager.Instance().audioSource.stop();
    }

    private playSound(): void {
        AudioManager.Instance().setSoundEnabled(true);
        Eventer.getInstance().emit(Config.changeSound, true);
        // AudioManager.Instance().musicOn();
    }

    protected onDestroy(): void {
        this.offEvent();
    }

}

