import { Timer } from "./Timer";

/**
 * 动作队列 按顺序执行队列里动作
 */
export class ActionQueue {
    private _id: number = 0;
    private _actions: Action[];
    private _curAction: Action;
    private _timeOutKey: number = 0;

    public constructor() {
        this._actions = [];
    }

    /**
     * 通过方法添加动作队列
     * @param delay 延迟执行 单位ms
     * @param func 方法
     * @param obj 方法调用对象
     * @param args 方法参数
     * @returns 生产的action
     */
    public addActionByFunc(delay: number, func: Function, obj: any, args?: any) {
        this._id++;
        let action = new Action(this._id, delay, func, obj, args);
        this.addAction(action);
        return action;
    }

    public addAction(action: Action) {
        this._actions.push(action);
    }

    public removeAction(id: number) {
        for (let i = this._actions.length - 1; i >= 0; i--) {
            let a = this._actions[i];
            if (a.id == id) {
                this._actions.splice(i, 1);
            }
        }
    }

    /**
     * 开始执行队列动作
     * @returns 
     */
    public execute() {
        if (this._actions.length == 0 || this._curAction != null) {
            return;
        }

        this._curAction = this._actions.shift();
        this._curAction.action();  //执行动作
        this._timeOutKey = Timer.setTimeOut(this, () => {
            this._curAction = null;
            this.execute();
        }, this._curAction.delay);
    }

    /**
     * 强制执行一个动作(不等上一个结束)
     */
    public forceNext() {
        Timer.clearTimeOut(this._timeOutKey);
        this._curAction = null;
        this.execute();
    }

    public clear() {
        Timer.clearTimeOut(this._timeOutKey);
        this._actions.length = 0;
        this._curAction = null;
    }
}

/**
 * 动作
 */
export class Action {
    private _id: number;
    private _action: Function;
    private _actionObj: any;
    private _actionArgs: any;
    private _delay: number;

    public constructor(id: number, delay: number, action: Function, obj: any, args?: any) {
        this._id = id;
        this._delay = delay;
        this._action = action;
        this._actionObj = obj;
        this._actionArgs = args;
    }

    public get id() {
        return this._id;
    }

    public get delay() {
        return this._delay;
    }

    public action() {
        if (this._action && this._actionObj) {
            this._action.call(this._actionObj, this._actionArgs);
        }
    }
}