import { _decorator, Node, sp } from 'cc';
import { MainComBase } from './MainComBase';
import { Label } from 'cc';
import { RollValue } from '../../../../rollCommon/script/views/RollValue';
import { Global } from '../../../../../scripts/main/Global';
import { UIManager } from '../../../../../scripts/framework/ui/UIManager';
import { UIID_GAME } from '../../UIDefined';
import { Timer } from '../../utils/Timer';

export class FreeGameView extends MainComBase {
    private _root: Node;
    private _freeGame_ske: sp.Skeleton;
    private _win_score: RollValue;
    private _freeGameTimes: Node;
    private _freeTime_group: Node;
    private _callback: Function;
    private _caller: any;
    private _boomAnim: Node;
    private _freeGameNum: number;
    protected _init(): void {
        this._root = this._comRoot.getChildByName("FreeGameView");
        this._freeGame_ske = this._root.getChildByName("free_ske").getComponent(sp.Skeleton);
        this._freeTime_group = this._root.getChildByName("freeTips_group");
        this._freeGameTimes = this._freeTime_group.getChildByName("freeGameTimes");
        this._win_score = this._root.getChildByName("win_score").getComponent(RollValue);
        this._win_score.init(false, 700);

        this._boomAnim = this._root.getChildByPath("boomActNode/baodian");
        this._boomAnim.active = false;
    }

    protected _addEvent(): void {
    }
    protected _removeEvent(): void {
    }

    public initPrefix() {
        this._win_score.setPrefix(Global.currencyName);
    }

    //设置展示的免费次数
    public setFreeGameTimes(times: number): void {
        this._freeGameNum = times;
        this._freeGameTimes.getComponent(Label).string = this._freeGameNum.toString();
        this._freeGameTimes.active = true;
    }

    public updateFreeGameTimes(): void {
        if (this._freeGameNum > 0) {
            this._freeGameNum--;
            this._freeGameTimes.getComponent(Label).string = this._freeGameNum.toString();
        }
        this._freeGameTimes.active = true;
    }

    public recovery(): void {
        this.show();
    }

    // 播放free火动效+ open 帮助界面
    public playFreeSke(callback: Function, caller: any): void {
        this._callback = callback;
        this._caller = caller;    
        this._root.active = true; 
        this._freeGame_ske.node.active = true;
        this._freeGame_ske.clearTrack(0);
        this._freeGame_ske.setToSetupPose();
        this._freeGame_ske.setAnimation(0, "animation", false);
        
        Timer.setTimeOut(this, () => {
            // 恢复初始中free数据盘面
            this._caller._resetFreeRoll();
            UIManager.getInstance().open(UIID_GAME.GameModelHelp, {gameModel:0, call:this._freeGameskeCallback, thisObj:this});
        }, 600);
    }

    public show(): void {
        this._root.active = true;
    }
    
    public hide(): void {
        this._root.active = false;
    }

    public setWinScore(value: number) {
        this._win_score.setValue(value);
    }

    private _freeGameskeCallback(): void {
        this._freeGame_ske.setCompleteListener(null);
        this._freeGame_ske.setEventListener(null);
        if (this._callback) {
            this._freeGame_ske.clearTrack(0);
            this._freeGame_ske.setToSetupPose();
            this._freeGame_ske.node.active = false;
            this._callback.call(this._caller);
        }
    }
}